window.WB_DATA = {"samples": {"explore": {"beginner": {"index.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <title>Vending machine</title>\n  <link rel=\"stylesheet\" href=\"style.css\">\n</head>\n<body>\n  <header>\n    <h1>Vending machine</h1>\n    <nav>\n      <a href=\"index.html\">Machine</a>\n      <a href=\"restock.html?slot=A1\">Restock</a>\n      <a href=\"sales.html\">Sales</a>\n    </nav>\n  </header>\n\n  <main>\n    <p class=\"message\" data-message></p>\n\n    <!-- client.js fetches this address and repeats the template once for every row. -->\n    <section class=\"machine\" data-get=\"/api/list_slots\">\n      <template>\n        <article class=\"slot\">\n          <a class=\"slot-id\" data-href=\"item.html?slot={slot_id}\" data-field=\"slot_id\"></a>\n          <h2 data-field=\"item_name\"></h2>\n          <p class=\"price\" data-field=\"price_cents\" data-format=\"euros\"></p>\n          <p class=\"stock\"><span data-field=\"stock\"></span> left</p>\n          <button data-post=\"/api/buy_slot?slot={slot_id}\" data-success=\"Enjoy your snack.\">Buy</button>\n        </article>\n      </template>\n    </section>\n  </main>\n\n  <script src=\"client.js\"></script>\n</body>\n</html>\n", "item.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <title>One slot</title>\n  <link rel=\"stylesheet\" href=\"style.css\">\n</head>\n<body>\n  <header>\n    <h1>One slot</h1>\n    <nav>\n      <a href=\"index.html\">Machine</a>\n      <a href=\"restock.html?slot=A1\">Restock</a>\n      <a href=\"sales.html\">Sales</a>\n    </nav>\n  </header>\n\n  <main>\n    <p class=\"message\" data-message></p>\n\n    <!-- The address of this page ends in ?slot=A1, and {query.slot} reads that value. -->\n    <section data-get=\"/api/get_slot?slot={query.slot}\" data-one>\n      <template>\n        <article class=\"detail slot\">\n          <h2><span data-field=\"slot_id\"></span>: <span data-field=\"item_name\"></span></h2>\n          <p class=\"price\" data-field=\"price_cents\" data-format=\"euros\"></p>\n          <p class=\"stock\"><span data-field=\"stock\"></span> left</p>\n          <button data-post=\"/api/buy_slot?slot={slot_id}\" data-success=\"Enjoy your snack.\">Buy</button>\n          <a data-href=\"restock.html?slot={slot_id}\">Restock this slot</a>\n        </article>\n      </template>\n    </section>\n  </main>\n\n  <script src=\"client.js\"></script>\n</body>\n</html>\n", "restock.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <title>Restock</title>\n  <link rel=\"stylesheet\" href=\"style.css\">\n</head>\n<body>\n  <header>\n    <h1>Restock</h1>\n    <nav>\n      <a href=\"index.html\">Machine</a>\n      <a href=\"restock.html?slot=A1\">Restock</a>\n      <a href=\"sales.html\">Sales</a>\n    </nav>\n  </header>\n\n  <main>\n    <p class=\"message\" data-message></p>\n\n    <section data-get=\"/api/get_slot?slot={query.slot}\" data-one>\n      <template>\n        <p class=\"detail\"><strong data-field=\"item_name\"></strong> has <span data-field=\"stock\"></span> left.</p>\n      </template>\n    </section>\n\n    <!-- A form with data-post sends its fields as JSON. The input name becomes the key. -->\n    <form data-post=\"/api/restock_slot?slot={query.slot}\" data-success=\"Stock added.\">\n      <p><label>How many to add? <input name=\"amount\" type=\"number\" value=\"5\"></label></p>\n      <button>Add stock</button>\n    </form>\n  </main>\n\n  <script src=\"client.js\"></script>\n</body>\n</html>\n", "sales.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <title>Sales</title>\n  <link rel=\"stylesheet\" href=\"style.css\">\n</head>\n<body>\n  <header>\n    <h1>Sales</h1>\n    <nav>\n      <a href=\"index.html\">Machine</a>\n      <a href=\"restock.html?slot=A1\">Restock</a>\n      <a href=\"sales.html\">Sales</a>\n    </nav>\n  </header>\n\n  <main>\n    <p class=\"message\" data-message></p>\n\n    <table>\n      <thead>\n        <tr><th>Sale</th><th>Item</th><th>Price</th><th>Time</th></tr>\n      </thead>\n      <tbody data-get=\"/api/list_sales\">\n        <template>\n          <tr>\n            <td data-field=\"sale_id\"></td>\n            <td data-field=\"item_name\"></td>\n            <td data-field=\"price_cents\" data-format=\"euros\"></td>\n            <td data-field=\"sold_at\"></td>\n          </tr>\n        </template>\n      </tbody>\n    </table>\n  </main>\n\n  <script src=\"client.js\"></script>\n</body>\n</html>\n", "style.css": "/* style.css controls how the pages look. Change a value and the preview updates at once. */\n\n:root {\n  --page: #f7f5ef;\n  --card: #ffffff;\n  --ink: #1f2933;\n  --quiet: #5b6673;\n  --line: #d9d4c7;\n  --accent: #0b6e6e;\n  --accent-text: #ffffff;\n  --bad: #a4262c;\n  --good: #25663a;\n}\n\n* { box-sizing: border-box; }\n\nbody {\n  margin: 0;\n  background: var(--page);\n  color: var(--ink);\n  font: 16px/1.5 system-ui, sans-serif;\n}\n\nheader {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: baseline;\n  justify-content: space-between;\n  gap: 8px 24px;\n  padding: 16px 24px;\n  background: var(--card);\n  border-bottom: 1px solid var(--line);\n}\n\nh1 { margin: 0; font-size: 1.4rem; }\n\nnav a { margin-right: 16px; color: var(--accent); }\n\nmain { max-width: 900px; margin: 0 auto; padding: 24px; }\n\n/* The machine is a grid of cards, one for each slot. */\n.machine {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(190px, 1fr));\n  gap: 16px;\n}\n\n.slot {\n  background: var(--card);\n  border: 1px solid var(--line);\n  border-radius: 10px;\n  padding: 16px;\n}\n\n.slot h2 { margin: 4px 0; font-size: 1.1rem; }\n.slot .price { margin: 0; font-weight: 700; }\n.slot .stock { margin: 0 0 12px; color: var(--quiet); }\n.slot-id { font-weight: 700; color: var(--accent); }\n\n/* The data-stock attribute is added by client.js, so CSS can react to the data. */\n.slot[data-stock=\"0\"] { opacity: 0.6; }\n.slot[data-stock=\"0\"] .stock { color: var(--bad); }\n\nbutton {\n  font: inherit;\n  font-weight: 700;\n  background: var(--accent);\n  color: var(--accent-text);\n  border: none;\n  border-radius: 6px;\n  padding: 8px 16px;\n  cursor: pointer;\n}\n\ninput {\n  font: inherit;\n  padding: 7px 10px;\n  border: 1px solid var(--line);\n  border-radius: 6px;\n}\n\n.message { min-height: 1.5em; font-weight: 700; }\n.message[data-kind=\"ok\"] { color: var(--good); }\n.message[data-kind=\"error\"] { color: var(--bad); }\n\ntable { width: 100%; border-collapse: collapse; background: var(--card); }\nth, td { text-align: left; padding: 8px 12px; border-bottom: 1px solid var(--line); }\n\n.detail { background: var(--card); border: 1px solid var(--line); border-radius: 10px; padding: 20px; }\n.detail h2 { margin-top: 0; }\n", "client.js": "// client.js is the only JavaScript in these pages. It reads data- attributes in the HTML,\n// asks the server for data, and fills the page in. You can build a whole page with\n// HTML and CSS alone, because this file does the JavaScript part for you.\n//\n//   data-get=\"/api/slots\"        Fetch this address when the page loads and show the answer inside this element.\n//   <template>                   Put the markup to repeat for every row inside the element. The markup needs one outer element.\n//   data-one                     The answer is a list, but show only its first row.\n//   data-field=\"item_name\"       Put the value of this column into the text of this element.\n//   data-format=\"euros\"          Show a number of cents as euros.\n//   data-href=\"item.html?slot={slot_id}\"   Build a link from the values of the row.\n//   data-post=\"/api/slots/{slot_id}/buy\"   Send a POST request when this button is clicked or this form is sent.\n//   data-success=\"Enjoy.\"        Set the message to show when the server answers OK.\n//   data-message                 Mark the element that shows messages.\n//\n// After a POST succeeds, the script fetches every data-get address on the page again, so the page shows the new data.\n// The script gives each row it builds the attribute data-generated, so that it can find and replace those rows later.\n//\n// In a text such as {slot_id}, the braces take a value from the row. In {query.slot} they\n// take a value from the address of the page, such as item.html?slot=A1.\n\n// The values after the question mark in the page's address, such as { slot: \"A1\" } for item.html?slot=A1.\n// The workbench supplies window.pageQuery because its pages do not have separate addresses.\n// On a real website you would read window.location.search instead.\nconst addressValues = Object.fromEntries(new URLSearchParams(window.pageQuery || window.location.search));\n\n// Replace every {name} or {query.name} in a text with a value, made safe for use in an address.\nfunction fillIn(text, row) {\n  return text.replace(/\\{(query\\.)?(\\w+)\\}/g, (_wholeMatch, queryPrefix, name) => {\n    const source = queryPrefix ? addressValues : row;\n    return encodeURIComponent(source[name] ?? \"\");\n  });\n}\n\n// Turn a number of cents into text such as \u20ac1.75.\nfunction formatValue(value, format) {\n  if (format === \"euros\") {\n    return \"\u20ac\" + (Number(value) / 100).toFixed(2);\n  }\n  return value;\n}\n\n// Show a message to the visitor, in the nearest element marked data-message.\nfunction showMessage(text, isError) {\n  const messageBox = document.querySelector(\"[data-message]\");\n  if (!messageBox) {\n    return;\n  }\n  messageBox.textContent = text;\n  messageBox.dataset.kind = isError ? \"error\" : \"ok\";\n}\n\n// Fetch the data for one section and rebuild its rows.\nasync function loadSection(section) {\n  // A section has no row yet, so its address can use {query.name} but not {column}.\n  const response = await fetch(fillIn(section.dataset.get, {}));\n  const answer = await response.json();\n  if (!response.ok) {\n    showMessage(answer.error, true);\n    return;\n  }\n\n  let rows = Array.isArray(answer) ? answer : [answer];\n  if (section.hasAttribute(\"data-one\")) {\n    rows = rows.slice(0, 1);\n  }\n\n  const template = section.querySelector(\"template\");\n  section.querySelectorAll(\"[data-generated]\").forEach((oldRow) => oldRow.remove());\n\n  for (const row of rows) {\n    const rowElement = template.content.firstElementChild.cloneNode(true);\n    rowElement.dataset.generated = \"\";\n\n    // Every column also becomes a data- attribute, so CSS can write rules such as [data-stock=\"0\"].\n    for (const [column, value] of Object.entries(row)) {\n      rowElement.dataset[column] = value;\n    }\n    rowElement.querySelectorAll(\"[data-field]\").forEach((element) => {\n      element.textContent = formatValue(row[element.dataset.field], element.dataset.format);\n    });\n    rowElement.querySelectorAll(\"[data-href]\").forEach((link) => {\n      link.setAttribute(\"href\", fillIn(link.dataset.href, row));\n    });\n    section.append(rowElement);\n  }\n}\n\n// Send a POST request for a button or a form, then refresh every section on the page.\nasync function sendPost(element, body) {\n  // A button inside a generated row can use that row's columns in its address, such as {slot_id}.\n  const row = element.closest(\"[data-generated]\")?.dataset ?? {};\n  const response = await fetch(fillIn(element.dataset.post, row), {\n    method: \"POST\",\n    headers: { \"Content-Type\": \"application/json\" },\n    body: JSON.stringify(body),\n  });\n  const answer = await response.json();\n  showMessage(response.ok ? element.dataset.success || \"Done.\" : answer.error, !response.ok);\n  if (response.ok) {\n    document.querySelectorAll(\"[data-get]\").forEach(loadSection);\n  }\n}\n\n// One listener on the whole document handles every button, including buttons added later.\ndocument.addEventListener(\"click\", (event) => {\n  const button = event.target.closest(\"button[data-post]\");\n  if (button) {\n    sendPost(button, {});\n  }\n});\n\n// A form sends its fields as JSON. Numbers in the fields are converted from text to numbers.\ndocument.addEventListener(\"submit\", (event) => {\n  const form = event.target.closest(\"form[data-post]\");\n  if (!form) {\n    return;\n  }\n  event.preventDefault();\n  const body = {};\n  for (const [name, value] of new FormData(form)) {\n    body[name] = value !== \"\" && !Number.isNaN(Number(value)) ? Number(value) : value;\n  }\n  sendPost(form, body);\n});\n\ndocument.querySelectorAll(\"[data-get]\").forEach(loadSection);\n", "schema.sql": "-- schema.sql describes the tables and the rows they start with.\n-- The workbench runs this whole file again when you press \"Reset database\".\n\n-- Remove the old tables first, so that this file gives the same result every time it runs.\n-- sales goes first because it refers to slots.\nDROP TABLE IF EXISTS sales;\nDROP TABLE IF EXISTS slots;\n\n-- Each row describes one place in the machine that holds a product.\n-- A CHECK rule makes the database refuse a negative price or a negative stock.\nCREATE TABLE slots (\n  slot_id     TEXT PRIMARY KEY,\n  item_name   TEXT NOT NULL,\n  price_cents INTEGER NOT NULL CHECK (price_cents >= 0),\n  stock       INTEGER NOT NULL CHECK (stock >= 0)\n);\n\n-- Each row records one purchase. The price is copied into the sale, so a later price change does not alter old sales.\nCREATE TABLE sales (\n  sale_id     INTEGER PRIMARY KEY AUTOINCREMENT,\n  slot_id     TEXT NOT NULL REFERENCES slots (slot_id),\n  price_cents INTEGER NOT NULL,\n  sold_at     TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\n\nINSERT INTO slots (slot_id, item_name, price_cents, stock) VALUES\n  ('A1', 'Sparkling Water', 175, 7),\n  ('A2', 'Salted Crisps',   150, 5),\n  ('B1', 'Oat Biscuit',     125, 0),\n  ('B2', 'Chocolate Bar',   200, 3);\n", "queries.sql": "-- queries.sql holds every question the server may ask the database.\n-- Each query starts with a comment of the form \"-- name: something\".\n-- A word with a colon in front, such as :slot, is a parameter.\n-- The server fills in each parameter safely, so a visitor cannot change the SQL itself.\n\n-- name: list_slots\nSELECT slot_id, item_name, price_cents, stock\nFROM slots\nORDER BY slot_id;\n\n-- name: get_slot\nSELECT slot_id, item_name, price_cents, stock\nFROM slots\nWHERE slot_id = :slot;\n\n-- name: buy_slot\n-- This query has two statements that succeed or fail together. Both check that stock is above zero,\n-- so a sold-out slot records no sale and loses no stock.\n-- The INSERT comes first on purpose. If the UPDATE ran first, the last item would leave stock at zero,\n-- and the INSERT would then find no stock and record no sale.\nINSERT INTO sales (slot_id, price_cents)\nSELECT slot_id, price_cents FROM slots WHERE slot_id = :slot AND stock > 0;\nUPDATE slots SET stock = stock - 1 WHERE slot_id = :slot AND stock > 0;\n\n-- name: restock_slot\n-- The check on :amount stops a negative number from removing stock.\nUPDATE slots SET stock = stock + :amount WHERE slot_id = :slot AND :amount > 0;\n\n-- name: list_sales\nSELECT sales.sale_id, slots.item_name, sales.price_cents, sales.sold_at\nFROM sales\nJOIN slots ON slots.slot_id = sales.slot_id\nORDER BY sales.sale_id DESC\nLIMIT 20;\n", "routes.txt": "# routes.txt says which request runs which query.\n# Each line has four columns: the method, the path, the query name, and the shape of the answer.\n#\n#   rows    the answer is a list of rows, which is empty when nothing matches\n#   one     the answer is a single row, or the server sends 404 when nothing matches\n#   change  the answer says how many rows changed, or the server sends 409 when no row changed\n#\n# A word with a colon in front, such as :slot, is taken from the path of the request.\n\nGET   /api/slots                 list_slots     rows\nGET   /api/slots/:slot           get_slot       one\nPOST  /api/slots/:slot/buy       buy_slot       change\nPOST  /api/slots/:slot/restock   restock_slot   change\nGET   /api/sales                 list_sales     rows\n", "handlers.ts": "// handlers.ts holds your routes. A route says: when this request arrives, run this function.\n//\n// These names come from server.ts and are ready to use:\n//   route(method, pattern, handler)   registers a route. A word such as :slot in the pattern is read from the path.\n//   json(body)                        answers 200 with this body\n//   fail(status, message)             answers with an error status and a message\n//   db.all(sql, params)               runs a query and returns every row\n//   db.get(sql, params)               runs a query and returns the first row, or undefined\n//   db.run(sql, params)               runs a statement that changes data and returns { changes }\n//   db.transaction(work)              runs work as one unit that succeeds or fails as a whole\n//   queries.list_slots.sql            holds the text of a query from queries.sql\n\nroute(\"GET\", \"/api/slots\", () => {\n  return json(db.all(queries.list_slots.sql));\n});\n\nroute(\"GET\", \"/api/slots/:slot\", (request) => {\n  const slot = db.get(queries.get_slot.sql, { slot: request.params.slot });\n  if (!slot) {\n    return fail(404, `There is no slot called ${request.params.slot}.`);\n  }\n  return json(slot);\n});\n\nroute(\"POST\", \"/api/slots/:slot/buy\", (request) => {\n  const slotId = request.params.slot;\n\n  // Both statements run inside one transaction, so the sale and the stock change happen together.\n  const bought = db.transaction(() => {\n    const update = db.run(\n      \"UPDATE slots SET stock = stock - 1 WHERE slot_id = :slot AND stock > 0\",\n      { slot: slotId }\n    );\n    // Nothing was updated, so the slot is sold out or does not exist. Leaving the transaction here changes nothing.\n    if (update.changes === 0) {\n      return false;\n    }\n    db.run(\n      \"INSERT INTO sales (slot_id, price_cents) SELECT slot_id, price_cents FROM slots WHERE slot_id = :slot\",\n      { slot: slotId }\n    );\n    return true;\n  });\n\n  if (!bought) {\n    return fail(409, \"That slot is sold out, or it does not exist.\");\n  }\n  return json(db.get(queries.get_slot.sql, { slot: slotId }));\n});\n\nroute(\"POST\", \"/api/slots/:slot/restock\", (request) => {\n  const amount = Number(request.body.amount);\n  if (!Number.isInteger(amount) || amount < 1) {\n    return fail(400, \"The amount must be a whole number of at least 1.\");\n  }\n  const result = db.run(queries.restock_slot.sql, { slot: request.params.slot, amount });\n  if (result.changes === 0) {\n    return fail(404, `There is no slot called ${request.params.slot}.`);\n  }\n  return json(db.get(queries.get_slot.sql, { slot: request.params.slot }));\n});\n\nroute(\"GET\", \"/api/sales\", () => {\n  return json(db.all(queries.list_sales.sql));\n});\n", "handlers.py": "# handlers.py holds your routes. A route says: when this request arrives, run this function.\n#\n# These names come from server.py and are ready to use:\n#   @route(method, pattern)   registers the function below it. A word such as :slot is read from the path.\n#   ok(body)                  answers 200 with this body\n#   fail(status, message)     answers with an error status and a message\n#   db.all(sql, params)       runs a query and returns every row\n#   db.get(sql, params)       runs a query and returns the first row, or None\n#   db.run(sql, params)       runs a statement that changes data and returns a result with .changes\n#   with db.transaction():    runs the indented lines as one unit that succeeds or fails as a whole\n#   queries[\"list_slots\"][\"sql\"]   holds the text of a query from queries.sql\n\n\n@route(\"GET\", \"/api/slots\")\ndef list_slots(request):\n    return ok(db.all(queries[\"list_slots\"][\"sql\"]))\n\n\n@route(\"GET\", \"/api/slots/:slot\")\ndef get_slot(request):\n    slot = db.get(queries[\"get_slot\"][\"sql\"], {\"slot\": request.params[\"slot\"]})\n    if slot is None:\n        return fail(404, f\"There is no slot called {request.params['slot']}.\")\n    return ok(slot)\n\n\n@route(\"POST\", \"/api/slots/:slot/buy\")\ndef buy_slot(request):\n    slot_id = request.params[\"slot\"]\n\n    # Both statements run inside one transaction, so the sale and the stock change happen together.\n    with db.transaction():\n        update = db.run(\n            \"UPDATE slots SET stock = stock - 1 WHERE slot_id = :slot AND stock > 0\",\n            {\"slot\": slot_id},\n        )\n        # Nothing was updated, so the slot is sold out or does not exist. Leaving the with block here changes nothing.\n        if update.changes == 0:\n            return fail(409, \"That slot is sold out, or it does not exist.\")\n        db.run(\n            \"INSERT INTO sales (slot_id, price_cents) SELECT slot_id, price_cents FROM slots WHERE slot_id = :slot\",\n            {\"slot\": slot_id},\n        )\n\n    return ok(db.get(queries[\"get_slot\"][\"sql\"], {\"slot\": slot_id}))\n\n\n@route(\"POST\", \"/api/slots/:slot/restock\")\ndef restock_slot(request):\n    amount = request.body.get(\"amount\")\n    if not isinstance(amount, int) or isinstance(amount, bool) or amount < 1:\n        return fail(400, \"The amount must be a whole number of at least 1.\")\n    result = db.run(queries[\"restock_slot\"][\"sql\"], {\"slot\": request.params[\"slot\"], \"amount\": amount})\n    if result.changes == 0:\n        return fail(404, f\"There is no slot called {request.params['slot']}.\")\n    return ok(db.get(queries[\"get_slot\"][\"sql\"], {\"slot\": request.params[\"slot\"]}))\n\n\n@route(\"GET\", \"/api/sales\")\ndef list_sales(request):\n    return ok(db.all(queries[\"list_sales\"][\"sql\"]))\n"}, "intermediate": {"index.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <title>Vending machine</title>\n  <link rel=\"stylesheet\" href=\"style.css\">\n</head>\n<body>\n  <header>\n    <h1>Vending machine</h1>\n    <nav>\n      <a href=\"index.html\">Machine</a>\n      <a href=\"restock.html?slot=A1\">Restock</a>\n      <a href=\"sales.html\">Sales</a>\n    </nav>\n  </header>\n\n  <main>\n    <p class=\"message\" data-message></p>\n\n    <!-- client.js fetches this address and repeats the template once for every row. -->\n    <section class=\"machine\" data-get=\"/api/slots\">\n      <template>\n        <article class=\"slot\">\n          <a class=\"slot-id\" data-href=\"item.html?slot={slot_id}\" data-field=\"slot_id\"></a>\n          <h2 data-field=\"item_name\"></h2>\n          <p class=\"price\" data-field=\"price_cents\" data-format=\"euros\"></p>\n          <p class=\"stock\"><span data-field=\"stock\"></span> left</p>\n          <button data-post=\"/api/slots/{slot_id}/buy\" data-success=\"Enjoy your snack.\">Buy</button>\n        </article>\n      </template>\n    </section>\n  </main>\n\n  <script src=\"client.js\"></script>\n</body>\n</html>\n", "item.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <title>One slot</title>\n  <link rel=\"stylesheet\" href=\"style.css\">\n</head>\n<body>\n  <header>\n    <h1>One slot</h1>\n    <nav>\n      <a href=\"index.html\">Machine</a>\n      <a href=\"restock.html?slot=A1\">Restock</a>\n      <a href=\"sales.html\">Sales</a>\n    </nav>\n  </header>\n\n  <main>\n    <p class=\"message\" data-message></p>\n\n    <!-- The address of this page ends in ?slot=A1, and {query.slot} reads that value. -->\n    <section data-get=\"/api/slots/{query.slot}\" data-one>\n      <template>\n        <article class=\"detail slot\">\n          <h2><span data-field=\"slot_id\"></span>: <span data-field=\"item_name\"></span></h2>\n          <p class=\"price\" data-field=\"price_cents\" data-format=\"euros\"></p>\n          <p class=\"stock\"><span data-field=\"stock\"></span> left</p>\n          <button data-post=\"/api/slots/{slot_id}/buy\" data-success=\"Enjoy your snack.\">Buy</button>\n          <a data-href=\"restock.html?slot={slot_id}\">Restock this slot</a>\n        </article>\n      </template>\n    </section>\n  </main>\n\n  <script src=\"client.js\"></script>\n</body>\n</html>\n", "restock.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <title>Restock</title>\n  <link rel=\"stylesheet\" href=\"style.css\">\n</head>\n<body>\n  <header>\n    <h1>Restock</h1>\n    <nav>\n      <a href=\"index.html\">Machine</a>\n      <a href=\"restock.html?slot=A1\">Restock</a>\n      <a href=\"sales.html\">Sales</a>\n    </nav>\n  </header>\n\n  <main>\n    <p class=\"message\" data-message></p>\n\n    <section data-get=\"/api/slots/{query.slot}\" data-one>\n      <template>\n        <p class=\"detail\"><strong data-field=\"item_name\"></strong> has <span data-field=\"stock\"></span> left.</p>\n      </template>\n    </section>\n\n    <!-- A form with data-post sends its fields as JSON. The input name becomes the key. -->\n    <form data-post=\"/api/slots/{query.slot}/restock\" data-success=\"Stock added.\">\n      <p><label>How many to add? <input name=\"amount\" type=\"number\" value=\"5\"></label></p>\n      <button>Add stock</button>\n    </form>\n  </main>\n\n  <script src=\"client.js\"></script>\n</body>\n</html>\n", "sales.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <title>Sales</title>\n  <link rel=\"stylesheet\" href=\"style.css\">\n</head>\n<body>\n  <header>\n    <h1>Sales</h1>\n    <nav>\n      <a href=\"index.html\">Machine</a>\n      <a href=\"restock.html?slot=A1\">Restock</a>\n      <a href=\"sales.html\">Sales</a>\n    </nav>\n  </header>\n\n  <main>\n    <p class=\"message\" data-message></p>\n\n    <table>\n      <thead>\n        <tr><th>Sale</th><th>Item</th><th>Price</th><th>Time</th></tr>\n      </thead>\n      <tbody data-get=\"/api/sales\">\n        <template>\n          <tr>\n            <td data-field=\"sale_id\"></td>\n            <td data-field=\"item_name\"></td>\n            <td data-field=\"price_cents\" data-format=\"euros\"></td>\n            <td data-field=\"sold_at\"></td>\n          </tr>\n        </template>\n      </tbody>\n    </table>\n  </main>\n\n  <script src=\"client.js\"></script>\n</body>\n</html>\n", "style.css": "/* style.css controls how the pages look. Change a value and the preview updates at once. */\n\n:root {\n  --page: #f7f5ef;\n  --card: #ffffff;\n  --ink: #1f2933;\n  --quiet: #5b6673;\n  --line: #d9d4c7;\n  --accent: #0b6e6e;\n  --accent-text: #ffffff;\n  --bad: #a4262c;\n  --good: #25663a;\n}\n\n* { box-sizing: border-box; }\n\nbody {\n  margin: 0;\n  background: var(--page);\n  color: var(--ink);\n  font: 16px/1.5 system-ui, sans-serif;\n}\n\nheader {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: baseline;\n  justify-content: space-between;\n  gap: 8px 24px;\n  padding: 16px 24px;\n  background: var(--card);\n  border-bottom: 1px solid var(--line);\n}\n\nh1 { margin: 0; font-size: 1.4rem; }\n\nnav a { margin-right: 16px; color: var(--accent); }\n\nmain { max-width: 900px; margin: 0 auto; padding: 24px; }\n\n/* The machine is a grid of cards, one for each slot. */\n.machine {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(190px, 1fr));\n  gap: 16px;\n}\n\n.slot {\n  background: var(--card);\n  border: 1px solid var(--line);\n  border-radius: 10px;\n  padding: 16px;\n}\n\n.slot h2 { margin: 4px 0; font-size: 1.1rem; }\n.slot .price { margin: 0; font-weight: 700; }\n.slot .stock { margin: 0 0 12px; color: var(--quiet); }\n.slot-id { font-weight: 700; color: var(--accent); }\n\n/* The data-stock attribute is added by client.js, so CSS can react to the data. */\n.slot[data-stock=\"0\"] { opacity: 0.6; }\n.slot[data-stock=\"0\"] .stock { color: var(--bad); }\n\nbutton {\n  font: inherit;\n  font-weight: 700;\n  background: var(--accent);\n  color: var(--accent-text);\n  border: none;\n  border-radius: 6px;\n  padding: 8px 16px;\n  cursor: pointer;\n}\n\ninput {\n  font: inherit;\n  padding: 7px 10px;\n  border: 1px solid var(--line);\n  border-radius: 6px;\n}\n\n.message { min-height: 1.5em; font-weight: 700; }\n.message[data-kind=\"ok\"] { color: var(--good); }\n.message[data-kind=\"error\"] { color: var(--bad); }\n\ntable { width: 100%; border-collapse: collapse; background: var(--card); }\nth, td { text-align: left; padding: 8px 12px; border-bottom: 1px solid var(--line); }\n\n.detail { background: var(--card); border: 1px solid var(--line); border-radius: 10px; padding: 20px; }\n.detail h2 { margin-top: 0; }\n", "client.js": "// client.js is the only JavaScript in these pages. It reads data- attributes in the HTML,\n// asks the server for data, and fills the page in. You can build a whole page with\n// HTML and CSS alone, because this file does the JavaScript part for you.\n//\n//   data-get=\"/api/slots\"        Fetch this address when the page loads and show the answer inside this element.\n//   <template>                   Put the markup to repeat for every row inside the element. The markup needs one outer element.\n//   data-one                     The answer is a list, but show only its first row.\n//   data-field=\"item_name\"       Put the value of this column into the text of this element.\n//   data-format=\"euros\"          Show a number of cents as euros.\n//   data-href=\"item.html?slot={slot_id}\"   Build a link from the values of the row.\n//   data-post=\"/api/slots/{slot_id}/buy\"   Send a POST request when this button is clicked or this form is sent.\n//   data-success=\"Enjoy.\"        Set the message to show when the server answers OK.\n//   data-message                 Mark the element that shows messages.\n//\n// After a POST succeeds, the script fetches every data-get address on the page again, so the page shows the new data.\n// The script gives each row it builds the attribute data-generated, so that it can find and replace those rows later.\n//\n// In a text such as {slot_id}, the braces take a value from the row. In {query.slot} they\n// take a value from the address of the page, such as item.html?slot=A1.\n\n// The values after the question mark in the page's address, such as { slot: \"A1\" } for item.html?slot=A1.\n// The workbench supplies window.pageQuery because its pages do not have separate addresses.\n// On a real website you would read window.location.search instead.\nconst addressValues = Object.fromEntries(new URLSearchParams(window.pageQuery || window.location.search));\n\n// Replace every {name} or {query.name} in a text with a value, made safe for use in an address.\nfunction fillIn(text, row) {\n  return text.replace(/\\{(query\\.)?(\\w+)\\}/g, (_wholeMatch, queryPrefix, name) => {\n    const source = queryPrefix ? addressValues : row;\n    return encodeURIComponent(source[name] ?? \"\");\n  });\n}\n\n// Turn a number of cents into text such as \u20ac1.75.\nfunction formatValue(value, format) {\n  if (format === \"euros\") {\n    return \"\u20ac\" + (Number(value) / 100).toFixed(2);\n  }\n  return value;\n}\n\n// Show a message to the visitor, in the nearest element marked data-message.\nfunction showMessage(text, isError) {\n  const messageBox = document.querySelector(\"[data-message]\");\n  if (!messageBox) {\n    return;\n  }\n  messageBox.textContent = text;\n  messageBox.dataset.kind = isError ? \"error\" : \"ok\";\n}\n\n// Fetch the data for one section and rebuild its rows.\nasync function loadSection(section) {\n  // A section has no row yet, so its address can use {query.name} but not {column}.\n  const response = await fetch(fillIn(section.dataset.get, {}));\n  const answer = await response.json();\n  if (!response.ok) {\n    showMessage(answer.error, true);\n    return;\n  }\n\n  let rows = Array.isArray(answer) ? answer : [answer];\n  if (section.hasAttribute(\"data-one\")) {\n    rows = rows.slice(0, 1);\n  }\n\n  const template = section.querySelector(\"template\");\n  section.querySelectorAll(\"[data-generated]\").forEach((oldRow) => oldRow.remove());\n\n  for (const row of rows) {\n    const rowElement = template.content.firstElementChild.cloneNode(true);\n    rowElement.dataset.generated = \"\";\n\n    // Every column also becomes a data- attribute, so CSS can write rules such as [data-stock=\"0\"].\n    for (const [column, value] of Object.entries(row)) {\n      rowElement.dataset[column] = value;\n    }\n    rowElement.querySelectorAll(\"[data-field]\").forEach((element) => {\n      element.textContent = formatValue(row[element.dataset.field], element.dataset.format);\n    });\n    rowElement.querySelectorAll(\"[data-href]\").forEach((link) => {\n      link.setAttribute(\"href\", fillIn(link.dataset.href, row));\n    });\n    section.append(rowElement);\n  }\n}\n\n// Send a POST request for a button or a form, then refresh every section on the page.\nasync function sendPost(element, body) {\n  // A button inside a generated row can use that row's columns in its address, such as {slot_id}.\n  const row = element.closest(\"[data-generated]\")?.dataset ?? {};\n  const response = await fetch(fillIn(element.dataset.post, row), {\n    method: \"POST\",\n    headers: { \"Content-Type\": \"application/json\" },\n    body: JSON.stringify(body),\n  });\n  const answer = await response.json();\n  showMessage(response.ok ? element.dataset.success || \"Done.\" : answer.error, !response.ok);\n  if (response.ok) {\n    document.querySelectorAll(\"[data-get]\").forEach(loadSection);\n  }\n}\n\n// One listener on the whole document handles every button, including buttons added later.\ndocument.addEventListener(\"click\", (event) => {\n  const button = event.target.closest(\"button[data-post]\");\n  if (button) {\n    sendPost(button, {});\n  }\n});\n\n// A form sends its fields as JSON. Numbers in the fields are converted from text to numbers.\ndocument.addEventListener(\"submit\", (event) => {\n  const form = event.target.closest(\"form[data-post]\");\n  if (!form) {\n    return;\n  }\n  event.preventDefault();\n  const body = {};\n  for (const [name, value] of new FormData(form)) {\n    body[name] = value !== \"\" && !Number.isNaN(Number(value)) ? Number(value) : value;\n  }\n  sendPost(form, body);\n});\n\ndocument.querySelectorAll(\"[data-get]\").forEach(loadSection);\n", "schema.sql": "-- schema.sql describes the tables and the rows they start with.\n-- The workbench runs this whole file again when you press \"Reset database\".\n\n-- Remove the old tables first, so that this file gives the same result every time it runs.\n-- sales goes first because it refers to slots.\nDROP TABLE IF EXISTS sales;\nDROP TABLE IF EXISTS slots;\n\n-- Each row describes one place in the machine that holds a product.\n-- A CHECK rule makes the database refuse a negative price or a negative stock.\nCREATE TABLE slots (\n  slot_id     TEXT PRIMARY KEY,\n  item_name   TEXT NOT NULL,\n  price_cents INTEGER NOT NULL CHECK (price_cents >= 0),\n  stock       INTEGER NOT NULL CHECK (stock >= 0)\n);\n\n-- Each row records one purchase. The price is copied into the sale, so a later price change does not alter old sales.\nCREATE TABLE sales (\n  sale_id     INTEGER PRIMARY KEY AUTOINCREMENT,\n  slot_id     TEXT NOT NULL REFERENCES slots (slot_id),\n  price_cents INTEGER NOT NULL,\n  sold_at     TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\n\nINSERT INTO slots (slot_id, item_name, price_cents, stock) VALUES\n  ('A1', 'Sparkling Water', 175, 7),\n  ('A2', 'Salted Crisps',   150, 5),\n  ('B1', 'Oat Biscuit',     125, 0),\n  ('B2', 'Chocolate Bar',   200, 3);\n", "queries.sql": "-- queries.sql holds every question the server may ask the database.\n-- Each query starts with a comment of the form \"-- name: something\".\n-- A word with a colon in front, such as :slot, is a parameter.\n-- The server fills in each parameter safely, so a visitor cannot change the SQL itself.\n\n-- name: list_slots\nSELECT slot_id, item_name, price_cents, stock\nFROM slots\nORDER BY slot_id;\n\n-- name: get_slot\nSELECT slot_id, item_name, price_cents, stock\nFROM slots\nWHERE slot_id = :slot;\n\n-- name: buy_slot\n-- This query has two statements that succeed or fail together. Both check that stock is above zero,\n-- so a sold-out slot records no sale and loses no stock.\n-- The INSERT comes first on purpose. If the UPDATE ran first, the last item would leave stock at zero,\n-- and the INSERT would then find no stock and record no sale.\nINSERT INTO sales (slot_id, price_cents)\nSELECT slot_id, price_cents FROM slots WHERE slot_id = :slot AND stock > 0;\nUPDATE slots SET stock = stock - 1 WHERE slot_id = :slot AND stock > 0;\n\n-- name: restock_slot\n-- The check on :amount stops a negative number from removing stock.\nUPDATE slots SET stock = stock + :amount WHERE slot_id = :slot AND :amount > 0;\n\n-- name: list_sales\nSELECT sales.sale_id, slots.item_name, sales.price_cents, sales.sold_at\nFROM sales\nJOIN slots ON slots.slot_id = sales.slot_id\nORDER BY sales.sale_id DESC\nLIMIT 20;\n", "routes.txt": "# routes.txt says which request runs which query.\n# Each line has four columns: the method, the path, the query name, and the shape of the answer.\n#\n#   rows    the answer is a list of rows, which is empty when nothing matches\n#   one     the answer is a single row, or the server sends 404 when nothing matches\n#   change  the answer says how many rows changed, or the server sends 409 when no row changed\n#\n# A word with a colon in front, such as :slot, is taken from the path of the request.\n\nGET   /api/slots                 list_slots     rows\nGET   /api/slots/:slot           get_slot       one\nPOST  /api/slots/:slot/buy       buy_slot       change\nPOST  /api/slots/:slot/restock   restock_slot   change\nGET   /api/sales                 list_sales     rows\n", "handlers.ts": "// handlers.ts holds your routes. A route says: when this request arrives, run this function.\n//\n// These names come from server.ts and are ready to use:\n//   route(method, pattern, handler)   registers a route. A word such as :slot in the pattern is read from the path.\n//   json(body)                        answers 200 with this body\n//   fail(status, message)             answers with an error status and a message\n//   db.all(sql, params)               runs a query and returns every row\n//   db.get(sql, params)               runs a query and returns the first row, or undefined\n//   db.run(sql, params)               runs a statement that changes data and returns { changes }\n//   db.transaction(work)              runs work as one unit that succeeds or fails as a whole\n//   queries.list_slots.sql            holds the text of a query from queries.sql\n\nroute(\"GET\", \"/api/slots\", () => {\n  return json(db.all(queries.list_slots.sql));\n});\n\nroute(\"GET\", \"/api/slots/:slot\", (request) => {\n  const slot = db.get(queries.get_slot.sql, { slot: request.params.slot });\n  if (!slot) {\n    return fail(404, `There is no slot called ${request.params.slot}.`);\n  }\n  return json(slot);\n});\n\nroute(\"POST\", \"/api/slots/:slot/buy\", (request) => {\n  const slotId = request.params.slot;\n\n  // Both statements run inside one transaction, so the sale and the stock change happen together.\n  const bought = db.transaction(() => {\n    const update = db.run(\n      \"UPDATE slots SET stock = stock - 1 WHERE slot_id = :slot AND stock > 0\",\n      { slot: slotId }\n    );\n    // Nothing was updated, so the slot is sold out or does not exist. Leaving the transaction here changes nothing.\n    if (update.changes === 0) {\n      return false;\n    }\n    db.run(\n      \"INSERT INTO sales (slot_id, price_cents) SELECT slot_id, price_cents FROM slots WHERE slot_id = :slot\",\n      { slot: slotId }\n    );\n    return true;\n  });\n\n  if (!bought) {\n    return fail(409, \"That slot is sold out, or it does not exist.\");\n  }\n  return json(db.get(queries.get_slot.sql, { slot: slotId }));\n});\n\nroute(\"POST\", \"/api/slots/:slot/restock\", (request) => {\n  const amount = Number(request.body.amount);\n  if (!Number.isInteger(amount) || amount < 1) {\n    return fail(400, \"The amount must be a whole number of at least 1.\");\n  }\n  const result = db.run(queries.restock_slot.sql, { slot: request.params.slot, amount });\n  if (result.changes === 0) {\n    return fail(404, `There is no slot called ${request.params.slot}.`);\n  }\n  return json(db.get(queries.get_slot.sql, { slot: request.params.slot }));\n});\n\nroute(\"GET\", \"/api/sales\", () => {\n  return json(db.all(queries.list_sales.sql));\n});\n", "handlers.py": "# handlers.py holds your routes. A route says: when this request arrives, run this function.\n#\n# These names come from server.py and are ready to use:\n#   @route(method, pattern)   registers the function below it. A word such as :slot is read from the path.\n#   ok(body)                  answers 200 with this body\n#   fail(status, message)     answers with an error status and a message\n#   db.all(sql, params)       runs a query and returns every row\n#   db.get(sql, params)       runs a query and returns the first row, or None\n#   db.run(sql, params)       runs a statement that changes data and returns a result with .changes\n#   with db.transaction():    runs the indented lines as one unit that succeeds or fails as a whole\n#   queries[\"list_slots\"][\"sql\"]   holds the text of a query from queries.sql\n\n\n@route(\"GET\", \"/api/slots\")\ndef list_slots(request):\n    return ok(db.all(queries[\"list_slots\"][\"sql\"]))\n\n\n@route(\"GET\", \"/api/slots/:slot\")\ndef get_slot(request):\n    slot = db.get(queries[\"get_slot\"][\"sql\"], {\"slot\": request.params[\"slot\"]})\n    if slot is None:\n        return fail(404, f\"There is no slot called {request.params['slot']}.\")\n    return ok(slot)\n\n\n@route(\"POST\", \"/api/slots/:slot/buy\")\ndef buy_slot(request):\n    slot_id = request.params[\"slot\"]\n\n    # Both statements run inside one transaction, so the sale and the stock change happen together.\n    with db.transaction():\n        update = db.run(\n            \"UPDATE slots SET stock = stock - 1 WHERE slot_id = :slot AND stock > 0\",\n            {\"slot\": slot_id},\n        )\n        # Nothing was updated, so the slot is sold out or does not exist. Leaving the with block here changes nothing.\n        if update.changes == 0:\n            return fail(409, \"That slot is sold out, or it does not exist.\")\n        db.run(\n            \"INSERT INTO sales (slot_id, price_cents) SELECT slot_id, price_cents FROM slots WHERE slot_id = :slot\",\n            {\"slot\": slot_id},\n        )\n\n    return ok(db.get(queries[\"get_slot\"][\"sql\"], {\"slot\": slot_id}))\n\n\n@route(\"POST\", \"/api/slots/:slot/restock\")\ndef restock_slot(request):\n    amount = request.body.get(\"amount\")\n    if not isinstance(amount, int) or isinstance(amount, bool) or amount < 1:\n        return fail(400, \"The amount must be a whole number of at least 1.\")\n    result = db.run(queries[\"restock_slot\"][\"sql\"], {\"slot\": request.params[\"slot\"], \"amount\": amount})\n    if result.changes == 0:\n        return fail(404, f\"There is no slot called {request.params['slot']}.\")\n    return ok(db.get(queries[\"get_slot\"][\"sql\"], {\"slot\": request.params[\"slot\"]}))\n\n\n@route(\"GET\", \"/api/sales\")\ndef list_sales(request):\n    return ok(db.all(queries[\"list_sales\"][\"sql\"]))\n"}, "advanced": {"index.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <title>Vending machine</title>\n  <link rel=\"stylesheet\" href=\"style.css\">\n</head>\n<body>\n  <header>\n    <h1>Vending machine</h1>\n    <nav>\n      <a href=\"index.html\">Machine</a>\n      <a href=\"restock.html?slot=A1\">Restock</a>\n      <a href=\"sales.html\">Sales</a>\n    </nav>\n  </header>\n\n  <main>\n    <p class=\"message\" data-message></p>\n\n    <!-- client.js fetches this address and repeats the template once for every row. -->\n    <section class=\"machine\" data-get=\"/api/slots\">\n      <template>\n        <article class=\"slot\">\n          <a class=\"slot-id\" data-href=\"item.html?slot={slot_id}\" data-field=\"slot_id\"></a>\n          <h2 data-field=\"item_name\"></h2>\n          <p class=\"price\" data-field=\"price_cents\" data-format=\"euros\"></p>\n          <p class=\"stock\"><span data-field=\"stock\"></span> left</p>\n          <button data-post=\"/api/slots/{slot_id}/buy\" data-success=\"Enjoy your snack.\">Buy</button>\n        </article>\n      </template>\n    </section>\n  </main>\n\n  <script src=\"client.js\"></script>\n</body>\n</html>\n", "item.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <title>One slot</title>\n  <link rel=\"stylesheet\" href=\"style.css\">\n</head>\n<body>\n  <header>\n    <h1>One slot</h1>\n    <nav>\n      <a href=\"index.html\">Machine</a>\n      <a href=\"restock.html?slot=A1\">Restock</a>\n      <a href=\"sales.html\">Sales</a>\n    </nav>\n  </header>\n\n  <main>\n    <p class=\"message\" data-message></p>\n\n    <!-- The address of this page ends in ?slot=A1, and {query.slot} reads that value. -->\n    <section data-get=\"/api/slots/{query.slot}\" data-one>\n      <template>\n        <article class=\"detail slot\">\n          <h2><span data-field=\"slot_id\"></span>: <span data-field=\"item_name\"></span></h2>\n          <p class=\"price\" data-field=\"price_cents\" data-format=\"euros\"></p>\n          <p class=\"stock\"><span data-field=\"stock\"></span> left</p>\n          <button data-post=\"/api/slots/{slot_id}/buy\" data-success=\"Enjoy your snack.\">Buy</button>\n          <a data-href=\"restock.html?slot={slot_id}\">Restock this slot</a>\n        </article>\n      </template>\n    </section>\n  </main>\n\n  <script src=\"client.js\"></script>\n</body>\n</html>\n", "restock.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <title>Restock</title>\n  <link rel=\"stylesheet\" href=\"style.css\">\n</head>\n<body>\n  <header>\n    <h1>Restock</h1>\n    <nav>\n      <a href=\"index.html\">Machine</a>\n      <a href=\"restock.html?slot=A1\">Restock</a>\n      <a href=\"sales.html\">Sales</a>\n    </nav>\n  </header>\n\n  <main>\n    <p class=\"message\" data-message></p>\n\n    <section data-get=\"/api/slots/{query.slot}\" data-one>\n      <template>\n        <p class=\"detail\"><strong data-field=\"item_name\"></strong> has <span data-field=\"stock\"></span> left.</p>\n      </template>\n    </section>\n\n    <!-- A form with data-post sends its fields as JSON. The input name becomes the key. -->\n    <form data-post=\"/api/slots/{query.slot}/restock\" data-success=\"Stock added.\">\n      <p><label>How many to add? <input name=\"amount\" type=\"number\" value=\"5\"></label></p>\n      <button>Add stock</button>\n    </form>\n  </main>\n\n  <script src=\"client.js\"></script>\n</body>\n</html>\n", "sales.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <title>Sales</title>\n  <link rel=\"stylesheet\" href=\"style.css\">\n</head>\n<body>\n  <header>\n    <h1>Sales</h1>\n    <nav>\n      <a href=\"index.html\">Machine</a>\n      <a href=\"restock.html?slot=A1\">Restock</a>\n      <a href=\"sales.html\">Sales</a>\n    </nav>\n  </header>\n\n  <main>\n    <p class=\"message\" data-message></p>\n\n    <table>\n      <thead>\n        <tr><th>Sale</th><th>Item</th><th>Price</th><th>Time</th></tr>\n      </thead>\n      <tbody data-get=\"/api/sales\">\n        <template>\n          <tr>\n            <td data-field=\"sale_id\"></td>\n            <td data-field=\"item_name\"></td>\n            <td data-field=\"price_cents\" data-format=\"euros\"></td>\n            <td data-field=\"sold_at\"></td>\n          </tr>\n        </template>\n      </tbody>\n    </table>\n  </main>\n\n  <script src=\"client.js\"></script>\n</body>\n</html>\n", "style.css": "/* style.css controls how the pages look. Change a value and the preview updates at once. */\n\n:root {\n  --page: #f7f5ef;\n  --card: #ffffff;\n  --ink: #1f2933;\n  --quiet: #5b6673;\n  --line: #d9d4c7;\n  --accent: #0b6e6e;\n  --accent-text: #ffffff;\n  --bad: #a4262c;\n  --good: #25663a;\n}\n\n* { box-sizing: border-box; }\n\nbody {\n  margin: 0;\n  background: var(--page);\n  color: var(--ink);\n  font: 16px/1.5 system-ui, sans-serif;\n}\n\nheader {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: baseline;\n  justify-content: space-between;\n  gap: 8px 24px;\n  padding: 16px 24px;\n  background: var(--card);\n  border-bottom: 1px solid var(--line);\n}\n\nh1 { margin: 0; font-size: 1.4rem; }\n\nnav a { margin-right: 16px; color: var(--accent); }\n\nmain { max-width: 900px; margin: 0 auto; padding: 24px; }\n\n/* The machine is a grid of cards, one for each slot. */\n.machine {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(190px, 1fr));\n  gap: 16px;\n}\n\n.slot {\n  background: var(--card);\n  border: 1px solid var(--line);\n  border-radius: 10px;\n  padding: 16px;\n}\n\n.slot h2 { margin: 4px 0; font-size: 1.1rem; }\n.slot .price { margin: 0; font-weight: 700; }\n.slot .stock { margin: 0 0 12px; color: var(--quiet); }\n.slot-id { font-weight: 700; color: var(--accent); }\n\n/* The data-stock attribute is added by client.js, so CSS can react to the data. */\n.slot[data-stock=\"0\"] { opacity: 0.6; }\n.slot[data-stock=\"0\"] .stock { color: var(--bad); }\n\nbutton {\n  font: inherit;\n  font-weight: 700;\n  background: var(--accent);\n  color: var(--accent-text);\n  border: none;\n  border-radius: 6px;\n  padding: 8px 16px;\n  cursor: pointer;\n}\n\ninput {\n  font: inherit;\n  padding: 7px 10px;\n  border: 1px solid var(--line);\n  border-radius: 6px;\n}\n\n.message { min-height: 1.5em; font-weight: 700; }\n.message[data-kind=\"ok\"] { color: var(--good); }\n.message[data-kind=\"error\"] { color: var(--bad); }\n\ntable { width: 100%; border-collapse: collapse; background: var(--card); }\nth, td { text-align: left; padding: 8px 12px; border-bottom: 1px solid var(--line); }\n\n.detail { background: var(--card); border: 1px solid var(--line); border-radius: 10px; padding: 20px; }\n.detail h2 { margin-top: 0; }\n", "client.js": "// client.js is the only JavaScript in these pages. It reads data- attributes in the HTML,\n// asks the server for data, and fills the page in. You can build a whole page with\n// HTML and CSS alone, because this file does the JavaScript part for you.\n//\n//   data-get=\"/api/slots\"        Fetch this address when the page loads and show the answer inside this element.\n//   <template>                   Put the markup to repeat for every row inside the element. The markup needs one outer element.\n//   data-one                     The answer is a list, but show only its first row.\n//   data-field=\"item_name\"       Put the value of this column into the text of this element.\n//   data-format=\"euros\"          Show a number of cents as euros.\n//   data-href=\"item.html?slot={slot_id}\"   Build a link from the values of the row.\n//   data-post=\"/api/slots/{slot_id}/buy\"   Send a POST request when this button is clicked or this form is sent.\n//   data-success=\"Enjoy.\"        Set the message to show when the server answers OK.\n//   data-message                 Mark the element that shows messages.\n//\n// After a POST succeeds, the script fetches every data-get address on the page again, so the page shows the new data.\n// The script gives each row it builds the attribute data-generated, so that it can find and replace those rows later.\n//\n// In a text such as {slot_id}, the braces take a value from the row. In {query.slot} they\n// take a value from the address of the page, such as item.html?slot=A1.\n\n// The values after the question mark in the page's address, such as { slot: \"A1\" } for item.html?slot=A1.\n// The workbench supplies window.pageQuery because its pages do not have separate addresses.\n// On a real website you would read window.location.search instead.\nconst addressValues = Object.fromEntries(new URLSearchParams(window.pageQuery || window.location.search));\n\n// Replace every {name} or {query.name} in a text with a value, made safe for use in an address.\nfunction fillIn(text, row) {\n  return text.replace(/\\{(query\\.)?(\\w+)\\}/g, (_wholeMatch, queryPrefix, name) => {\n    const source = queryPrefix ? addressValues : row;\n    return encodeURIComponent(source[name] ?? \"\");\n  });\n}\n\n// Turn a number of cents into text such as \u20ac1.75.\nfunction formatValue(value, format) {\n  if (format === \"euros\") {\n    return \"\u20ac\" + (Number(value) / 100).toFixed(2);\n  }\n  return value;\n}\n\n// Show a message to the visitor, in the nearest element marked data-message.\nfunction showMessage(text, isError) {\n  const messageBox = document.querySelector(\"[data-message]\");\n  if (!messageBox) {\n    return;\n  }\n  messageBox.textContent = text;\n  messageBox.dataset.kind = isError ? \"error\" : \"ok\";\n}\n\n// Fetch the data for one section and rebuild its rows.\nasync function loadSection(section) {\n  // A section has no row yet, so its address can use {query.name} but not {column}.\n  const response = await fetch(fillIn(section.dataset.get, {}));\n  const answer = await response.json();\n  if (!response.ok) {\n    showMessage(answer.error, true);\n    return;\n  }\n\n  let rows = Array.isArray(answer) ? answer : [answer];\n  if (section.hasAttribute(\"data-one\")) {\n    rows = rows.slice(0, 1);\n  }\n\n  const template = section.querySelector(\"template\");\n  section.querySelectorAll(\"[data-generated]\").forEach((oldRow) => oldRow.remove());\n\n  for (const row of rows) {\n    const rowElement = template.content.firstElementChild.cloneNode(true);\n    rowElement.dataset.generated = \"\";\n\n    // Every column also becomes a data- attribute, so CSS can write rules such as [data-stock=\"0\"].\n    for (const [column, value] of Object.entries(row)) {\n      rowElement.dataset[column] = value;\n    }\n    rowElement.querySelectorAll(\"[data-field]\").forEach((element) => {\n      element.textContent = formatValue(row[element.dataset.field], element.dataset.format);\n    });\n    rowElement.querySelectorAll(\"[data-href]\").forEach((link) => {\n      link.setAttribute(\"href\", fillIn(link.dataset.href, row));\n    });\n    section.append(rowElement);\n  }\n}\n\n// Send a POST request for a button or a form, then refresh every section on the page.\nasync function sendPost(element, body) {\n  // A button inside a generated row can use that row's columns in its address, such as {slot_id}.\n  const row = element.closest(\"[data-generated]\")?.dataset ?? {};\n  const response = await fetch(fillIn(element.dataset.post, row), {\n    method: \"POST\",\n    headers: { \"Content-Type\": \"application/json\" },\n    body: JSON.stringify(body),\n  });\n  const answer = await response.json();\n  showMessage(response.ok ? element.dataset.success || \"Done.\" : answer.error, !response.ok);\n  if (response.ok) {\n    document.querySelectorAll(\"[data-get]\").forEach(loadSection);\n  }\n}\n\n// One listener on the whole document handles every button, including buttons added later.\ndocument.addEventListener(\"click\", (event) => {\n  const button = event.target.closest(\"button[data-post]\");\n  if (button) {\n    sendPost(button, {});\n  }\n});\n\n// A form sends its fields as JSON. Numbers in the fields are converted from text to numbers.\ndocument.addEventListener(\"submit\", (event) => {\n  const form = event.target.closest(\"form[data-post]\");\n  if (!form) {\n    return;\n  }\n  event.preventDefault();\n  const body = {};\n  for (const [name, value] of new FormData(form)) {\n    body[name] = value !== \"\" && !Number.isNaN(Number(value)) ? Number(value) : value;\n  }\n  sendPost(form, body);\n});\n\ndocument.querySelectorAll(\"[data-get]\").forEach(loadSection);\n", "schema.sql": "-- schema.sql describes the tables and the rows they start with.\n-- The workbench runs this whole file again when you press \"Reset database\".\n\n-- Remove the old tables first, so that this file gives the same result every time it runs.\n-- sales goes first because it refers to slots.\nDROP TABLE IF EXISTS sales;\nDROP TABLE IF EXISTS slots;\n\n-- Each row describes one place in the machine that holds a product.\n-- A CHECK rule makes the database refuse a negative price or a negative stock.\nCREATE TABLE slots (\n  slot_id     TEXT PRIMARY KEY,\n  item_name   TEXT NOT NULL,\n  price_cents INTEGER NOT NULL CHECK (price_cents >= 0),\n  stock       INTEGER NOT NULL CHECK (stock >= 0)\n);\n\n-- Each row records one purchase. The price is copied into the sale, so a later price change does not alter old sales.\nCREATE TABLE sales (\n  sale_id     INTEGER PRIMARY KEY AUTOINCREMENT,\n  slot_id     TEXT NOT NULL REFERENCES slots (slot_id),\n  price_cents INTEGER NOT NULL,\n  sold_at     TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\n\nINSERT INTO slots (slot_id, item_name, price_cents, stock) VALUES\n  ('A1', 'Sparkling Water', 175, 7),\n  ('A2', 'Salted Crisps',   150, 5),\n  ('B1', 'Oat Biscuit',     125, 0),\n  ('B2', 'Chocolate Bar',   200, 3);\n", "queries.sql": "-- queries.sql holds every question the server may ask the database.\n-- Each query starts with a comment of the form \"-- name: something\".\n-- A word with a colon in front, such as :slot, is a parameter.\n-- The server fills in each parameter safely, so a visitor cannot change the SQL itself.\n\n-- name: list_slots\nSELECT slot_id, item_name, price_cents, stock\nFROM slots\nORDER BY slot_id;\n\n-- name: get_slot\nSELECT slot_id, item_name, price_cents, stock\nFROM slots\nWHERE slot_id = :slot;\n\n-- name: buy_slot\n-- This query has two statements that succeed or fail together. Both check that stock is above zero,\n-- so a sold-out slot records no sale and loses no stock.\n-- The INSERT comes first on purpose. If the UPDATE ran first, the last item would leave stock at zero,\n-- and the INSERT would then find no stock and record no sale.\nINSERT INTO sales (slot_id, price_cents)\nSELECT slot_id, price_cents FROM slots WHERE slot_id = :slot AND stock > 0;\nUPDATE slots SET stock = stock - 1 WHERE slot_id = :slot AND stock > 0;\n\n-- name: restock_slot\n-- The check on :amount stops a negative number from removing stock.\nUPDATE slots SET stock = stock + :amount WHERE slot_id = :slot AND :amount > 0;\n\n-- name: list_sales\nSELECT sales.sale_id, slots.item_name, sales.price_cents, sales.sold_at\nFROM sales\nJOIN slots ON slots.slot_id = sales.slot_id\nORDER BY sales.sale_id DESC\nLIMIT 20;\n", "routes.txt": "# routes.txt says which request runs which query.\n# Each line has four columns: the method, the path, the query name, and the shape of the answer.\n#\n#   rows    the answer is a list of rows, which is empty when nothing matches\n#   one     the answer is a single row, or the server sends 404 when nothing matches\n#   change  the answer says how many rows changed, or the server sends 409 when no row changed\n#\n# A word with a colon in front, such as :slot, is taken from the path of the request.\n\nGET   /api/slots                 list_slots     rows\nGET   /api/slots/:slot           get_slot       one\nPOST  /api/slots/:slot/buy       buy_slot       change\nPOST  /api/slots/:slot/restock   restock_slot   change\nGET   /api/sales                 list_sales     rows\n", "handlers.ts": "// handlers.ts holds your routes. A route says: when this request arrives, run this function.\n//\n// These names come from server.ts and are ready to use:\n//   route(method, pattern, handler)   registers a route. A word such as :slot in the pattern is read from the path.\n//   json(body)                        answers 200 with this body\n//   fail(status, message)             answers with an error status and a message\n//   db.all(sql, params)               runs a query and returns every row\n//   db.get(sql, params)               runs a query and returns the first row, or undefined\n//   db.run(sql, params)               runs a statement that changes data and returns { changes }\n//   db.transaction(work)              runs work as one unit that succeeds or fails as a whole\n//   queries.list_slots.sql            holds the text of a query from queries.sql\n\nroute(\"GET\", \"/api/slots\", () => {\n  return json(db.all(queries.list_slots.sql));\n});\n\nroute(\"GET\", \"/api/slots/:slot\", (request) => {\n  const slot = db.get(queries.get_slot.sql, { slot: request.params.slot });\n  if (!slot) {\n    return fail(404, `There is no slot called ${request.params.slot}.`);\n  }\n  return json(slot);\n});\n\nroute(\"POST\", \"/api/slots/:slot/buy\", (request) => {\n  const slotId = request.params.slot;\n\n  // Both statements run inside one transaction, so the sale and the stock change happen together.\n  const bought = db.transaction(() => {\n    const update = db.run(\n      \"UPDATE slots SET stock = stock - 1 WHERE slot_id = :slot AND stock > 0\",\n      { slot: slotId }\n    );\n    // Nothing was updated, so the slot is sold out or does not exist. Leaving the transaction here changes nothing.\n    if (update.changes === 0) {\n      return false;\n    }\n    db.run(\n      \"INSERT INTO sales (slot_id, price_cents) SELECT slot_id, price_cents FROM slots WHERE slot_id = :slot\",\n      { slot: slotId }\n    );\n    return true;\n  });\n\n  if (!bought) {\n    return fail(409, \"That slot is sold out, or it does not exist.\");\n  }\n  return json(db.get(queries.get_slot.sql, { slot: slotId }));\n});\n\nroute(\"POST\", \"/api/slots/:slot/restock\", (request) => {\n  const amount = Number(request.body.amount);\n  if (!Number.isInteger(amount) || amount < 1) {\n    return fail(400, \"The amount must be a whole number of at least 1.\");\n  }\n  const result = db.run(queries.restock_slot.sql, { slot: request.params.slot, amount });\n  if (result.changes === 0) {\n    return fail(404, `There is no slot called ${request.params.slot}.`);\n  }\n  return json(db.get(queries.get_slot.sql, { slot: request.params.slot }));\n});\n\nroute(\"GET\", \"/api/sales\", () => {\n  return json(db.all(queries.list_sales.sql));\n});\n", "handlers.py": "# handlers.py holds your routes. A route says: when this request arrives, run this function.\n#\n# These names come from server.py and are ready to use:\n#   @route(method, pattern)   registers the function below it. A word such as :slot is read from the path.\n#   ok(body)                  answers 200 with this body\n#   fail(status, message)     answers with an error status and a message\n#   db.all(sql, params)       runs a query and returns every row\n#   db.get(sql, params)       runs a query and returns the first row, or None\n#   db.run(sql, params)       runs a statement that changes data and returns a result with .changes\n#   with db.transaction():    runs the indented lines as one unit that succeeds or fails as a whole\n#   queries[\"list_slots\"][\"sql\"]   holds the text of a query from queries.sql\n\n\n@route(\"GET\", \"/api/slots\")\ndef list_slots(request):\n    return ok(db.all(queries[\"list_slots\"][\"sql\"]))\n\n\n@route(\"GET\", \"/api/slots/:slot\")\ndef get_slot(request):\n    slot = db.get(queries[\"get_slot\"][\"sql\"], {\"slot\": request.params[\"slot\"]})\n    if slot is None:\n        return fail(404, f\"There is no slot called {request.params['slot']}.\")\n    return ok(slot)\n\n\n@route(\"POST\", \"/api/slots/:slot/buy\")\ndef buy_slot(request):\n    slot_id = request.params[\"slot\"]\n\n    # Both statements run inside one transaction, so the sale and the stock change happen together.\n    with db.transaction():\n        update = db.run(\n            \"UPDATE slots SET stock = stock - 1 WHERE slot_id = :slot AND stock > 0\",\n            {\"slot\": slot_id},\n        )\n        # Nothing was updated, so the slot is sold out or does not exist. Leaving the with block here changes nothing.\n        if update.changes == 0:\n            return fail(409, \"That slot is sold out, or it does not exist.\")\n        db.run(\n            \"INSERT INTO sales (slot_id, price_cents) SELECT slot_id, price_cents FROM slots WHERE slot_id = :slot\",\n            {\"slot\": slot_id},\n        )\n\n    return ok(db.get(queries[\"get_slot\"][\"sql\"], {\"slot\": slot_id}))\n\n\n@route(\"POST\", \"/api/slots/:slot/restock\")\ndef restock_slot(request):\n    amount = request.body.get(\"amount\")\n    if not isinstance(amount, int) or isinstance(amount, bool) or amount < 1:\n        return fail(400, \"The amount must be a whole number of at least 1.\")\n    result = db.run(queries[\"restock_slot\"][\"sql\"], {\"slot\": request.params[\"slot\"], \"amount\": amount})\n    if result.changes == 0:\n        return fail(404, f\"There is no slot called {request.params['slot']}.\")\n    return ok(db.get(queries[\"get_slot\"][\"sql\"], {\"slot\": request.params[\"slot\"]}))\n\n\n@route(\"GET\", \"/api/sales\")\ndef list_sales(request):\n    return ok(db.all(queries[\"list_sales\"][\"sql\"]))\n"}}, "own": {"beginner": {"index.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <title>My page</title>\n  <link rel=\"stylesheet\" href=\"style.css\">\n</head>\n<body>\n  <header>\n    <h1>My page</h1>\n  </header>\n\n  <main>\n    <p class=\"message\" data-message></p>\n\n    <!-- client.js fetches this address and repeats the template once for every row. -->\n    <section class=\"machine\" data-get=\"/api/list_slots\">\n      <template>\n        <article class=\"slot\">\n          <h2 data-field=\"item_name\"></h2>\n          <p class=\"price\" data-field=\"price_cents\" data-format=\"euros\"></p>\n          <p class=\"stock\"><span data-field=\"stock\"></span> left</p>\n        </article>\n      </template>\n    </section>\n  </main>\n\n  <script src=\"client.js\"></script>\n</body>\n</html>\n", "schema.sql": "-- schema.sql describes the tables and the rows they start with.\n-- Replace it with your own tables, then press \"Reset database\".\n\nDROP TABLE IF EXISTS slots;\n\nCREATE TABLE slots (\n  slot_id     TEXT PRIMARY KEY,\n  item_name   TEXT NOT NULL,\n  price_cents INTEGER NOT NULL,\n  stock       INTEGER NOT NULL\n);\n\nINSERT INTO slots (slot_id, item_name, price_cents, stock) VALUES\n  ('A1', 'Sparkling Water', 175, 7),\n  ('A2', 'Salted Crisps',   150, 5);\n", "queries.sql": "-- queries.sql holds every question the server may ask the database.\n-- Each query starts with a comment of the form \"-- name: something\".\n-- A word with a colon in front, such as :slot, is a parameter.\n\n-- name: list_slots\nSELECT slot_id, item_name, price_cents, stock\nFROM slots\nORDER BY slot_id;\n", "routes.txt": "# routes.txt says which request runs which query.\n# Each line has four columns: the method, the path, the query name, and the shape of the answer.\n#   rows    the answer is a list of rows\n#   one     the answer is a single row, or 404 when nothing matches\n#   change  the answer says how many rows changed, or 409 when none did\n\nGET   /api/slots   list_slots   rows\n", "handlers.ts": "// handlers.ts holds your routes. A route says: when this request arrives, run this function.\n// Ready-made names: route, json, fail, db.all, db.get, db.run, db.transaction, queries.<name>.sql\n\nroute(\"GET\", \"/api/slots\", () => {\n  return json(db.all(queries.list_slots.sql));\n});\n", "handlers.py": "# handlers.py holds your routes. A route says: when this request arrives, run this function.\n# Ready-made names: route, ok, fail, db.all, db.get, db.run, db.transaction, queries[\"name\"][\"sql\"]\n\n\n@route(\"GET\", \"/api/slots\")\ndef list_slots(request):\n    return ok(db.all(queries[\"list_slots\"][\"sql\"]))\n", "style.css": "/* style.css controls how the pages look. Change a value and the preview updates at once. */\n\n:root {\n  --page: #f7f5ef;\n  --card: #ffffff;\n  --ink: #1f2933;\n  --quiet: #5b6673;\n  --line: #d9d4c7;\n  --accent: #0b6e6e;\n  --accent-text: #ffffff;\n  --bad: #a4262c;\n  --good: #25663a;\n}\n\n* { box-sizing: border-box; }\n\nbody {\n  margin: 0;\n  background: var(--page);\n  color: var(--ink);\n  font: 16px/1.5 system-ui, sans-serif;\n}\n\nheader {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: baseline;\n  justify-content: space-between;\n  gap: 8px 24px;\n  padding: 16px 24px;\n  background: var(--card);\n  border-bottom: 1px solid var(--line);\n}\n\nh1 { margin: 0; font-size: 1.4rem; }\n\nnav a { margin-right: 16px; color: var(--accent); }\n\nmain { max-width: 900px; margin: 0 auto; padding: 24px; }\n\n/* The machine is a grid of cards, one for each slot. */\n.machine {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(190px, 1fr));\n  gap: 16px;\n}\n\n.slot {\n  background: var(--card);\n  border: 1px solid var(--line);\n  border-radius: 10px;\n  padding: 16px;\n}\n\n.slot h2 { margin: 4px 0; font-size: 1.1rem; }\n.slot .price { margin: 0; font-weight: 700; }\n.slot .stock { margin: 0 0 12px; color: var(--quiet); }\n.slot-id { font-weight: 700; color: var(--accent); }\n\n/* The data-stock attribute is added by client.js, so CSS can react to the data. */\n.slot[data-stock=\"0\"] { opacity: 0.6; }\n.slot[data-stock=\"0\"] .stock { color: var(--bad); }\n\nbutton {\n  font: inherit;\n  font-weight: 700;\n  background: var(--accent);\n  color: var(--accent-text);\n  border: none;\n  border-radius: 6px;\n  padding: 8px 16px;\n  cursor: pointer;\n}\n\ninput {\n  font: inherit;\n  padding: 7px 10px;\n  border: 1px solid var(--line);\n  border-radius: 6px;\n}\n\n.message { min-height: 1.5em; font-weight: 700; }\n.message[data-kind=\"ok\"] { color: var(--good); }\n.message[data-kind=\"error\"] { color: var(--bad); }\n\ntable { width: 100%; border-collapse: collapse; background: var(--card); }\nth, td { text-align: left; padding: 8px 12px; border-bottom: 1px solid var(--line); }\n\n.detail { background: var(--card); border: 1px solid var(--line); border-radius: 10px; padding: 20px; }\n.detail h2 { margin-top: 0; }\n", "client.js": "// client.js is the only JavaScript in these pages. It reads data- attributes in the HTML,\n// asks the server for data, and fills the page in. You can build a whole page with\n// HTML and CSS alone, because this file does the JavaScript part for you.\n//\n//   data-get=\"/api/slots\"        Fetch this address when the page loads and show the answer inside this element.\n//   <template>                   Put the markup to repeat for every row inside the element. The markup needs one outer element.\n//   data-one                     The answer is a list, but show only its first row.\n//   data-field=\"item_name\"       Put the value of this column into the text of this element.\n//   data-format=\"euros\"          Show a number of cents as euros.\n//   data-href=\"item.html?slot={slot_id}\"   Build a link from the values of the row.\n//   data-post=\"/api/slots/{slot_id}/buy\"   Send a POST request when this button is clicked or this form is sent.\n//   data-success=\"Enjoy.\"        Set the message to show when the server answers OK.\n//   data-message                 Mark the element that shows messages.\n//\n// After a POST succeeds, the script fetches every data-get address on the page again, so the page shows the new data.\n// The script gives each row it builds the attribute data-generated, so that it can find and replace those rows later.\n//\n// In a text such as {slot_id}, the braces take a value from the row. In {query.slot} they\n// take a value from the address of the page, such as item.html?slot=A1.\n\n// The values after the question mark in the page's address, such as { slot: \"A1\" } for item.html?slot=A1.\n// The workbench supplies window.pageQuery because its pages do not have separate addresses.\n// On a real website you would read window.location.search instead.\nconst addressValues = Object.fromEntries(new URLSearchParams(window.pageQuery || window.location.search));\n\n// Replace every {name} or {query.name} in a text with a value, made safe for use in an address.\nfunction fillIn(text, row) {\n  return text.replace(/\\{(query\\.)?(\\w+)\\}/g, (_wholeMatch, queryPrefix, name) => {\n    const source = queryPrefix ? addressValues : row;\n    return encodeURIComponent(source[name] ?? \"\");\n  });\n}\n\n// Turn a number of cents into text such as \u20ac1.75.\nfunction formatValue(value, format) {\n  if (format === \"euros\") {\n    return \"\u20ac\" + (Number(value) / 100).toFixed(2);\n  }\n  return value;\n}\n\n// Show a message to the visitor, in the nearest element marked data-message.\nfunction showMessage(text, isError) {\n  const messageBox = document.querySelector(\"[data-message]\");\n  if (!messageBox) {\n    return;\n  }\n  messageBox.textContent = text;\n  messageBox.dataset.kind = isError ? \"error\" : \"ok\";\n}\n\n// Fetch the data for one section and rebuild its rows.\nasync function loadSection(section) {\n  // A section has no row yet, so its address can use {query.name} but not {column}.\n  const response = await fetch(fillIn(section.dataset.get, {}));\n  const answer = await response.json();\n  if (!response.ok) {\n    showMessage(answer.error, true);\n    return;\n  }\n\n  let rows = Array.isArray(answer) ? answer : [answer];\n  if (section.hasAttribute(\"data-one\")) {\n    rows = rows.slice(0, 1);\n  }\n\n  const template = section.querySelector(\"template\");\n  section.querySelectorAll(\"[data-generated]\").forEach((oldRow) => oldRow.remove());\n\n  for (const row of rows) {\n    const rowElement = template.content.firstElementChild.cloneNode(true);\n    rowElement.dataset.generated = \"\";\n\n    // Every column also becomes a data- attribute, so CSS can write rules such as [data-stock=\"0\"].\n    for (const [column, value] of Object.entries(row)) {\n      rowElement.dataset[column] = value;\n    }\n    rowElement.querySelectorAll(\"[data-field]\").forEach((element) => {\n      element.textContent = formatValue(row[element.dataset.field], element.dataset.format);\n    });\n    rowElement.querySelectorAll(\"[data-href]\").forEach((link) => {\n      link.setAttribute(\"href\", fillIn(link.dataset.href, row));\n    });\n    section.append(rowElement);\n  }\n}\n\n// Send a POST request for a button or a form, then refresh every section on the page.\nasync function sendPost(element, body) {\n  // A button inside a generated row can use that row's columns in its address, such as {slot_id}.\n  const row = element.closest(\"[data-generated]\")?.dataset ?? {};\n  const response = await fetch(fillIn(element.dataset.post, row), {\n    method: \"POST\",\n    headers: { \"Content-Type\": \"application/json\" },\n    body: JSON.stringify(body),\n  });\n  const answer = await response.json();\n  showMessage(response.ok ? element.dataset.success || \"Done.\" : answer.error, !response.ok);\n  if (response.ok) {\n    document.querySelectorAll(\"[data-get]\").forEach(loadSection);\n  }\n}\n\n// One listener on the whole document handles every button, including buttons added later.\ndocument.addEventListener(\"click\", (event) => {\n  const button = event.target.closest(\"button[data-post]\");\n  if (button) {\n    sendPost(button, {});\n  }\n});\n\n// A form sends its fields as JSON. Numbers in the fields are converted from text to numbers.\ndocument.addEventListener(\"submit\", (event) => {\n  const form = event.target.closest(\"form[data-post]\");\n  if (!form) {\n    return;\n  }\n  event.preventDefault();\n  const body = {};\n  for (const [name, value] of new FormData(form)) {\n    body[name] = value !== \"\" && !Number.isNaN(Number(value)) ? Number(value) : value;\n  }\n  sendPost(form, body);\n});\n\ndocument.querySelectorAll(\"[data-get]\").forEach(loadSection);\n"}, "intermediate": {"index.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <title>My page</title>\n  <link rel=\"stylesheet\" href=\"style.css\">\n</head>\n<body>\n  <header>\n    <h1>My page</h1>\n  </header>\n\n  <main>\n    <p class=\"message\" data-message></p>\n\n    <!-- client.js fetches this address and repeats the template once for every row. -->\n    <section class=\"machine\" data-get=\"/api/slots\">\n      <template>\n        <article class=\"slot\">\n          <h2 data-field=\"item_name\"></h2>\n          <p class=\"price\" data-field=\"price_cents\" data-format=\"euros\"></p>\n          <p class=\"stock\"><span data-field=\"stock\"></span> left</p>\n        </article>\n      </template>\n    </section>\n  </main>\n\n  <script src=\"client.js\"></script>\n</body>\n</html>\n", "schema.sql": "-- schema.sql describes the tables and the rows they start with.\n-- Replace it with your own tables, then press \"Reset database\".\n\nDROP TABLE IF EXISTS slots;\n\nCREATE TABLE slots (\n  slot_id     TEXT PRIMARY KEY,\n  item_name   TEXT NOT NULL,\n  price_cents INTEGER NOT NULL,\n  stock       INTEGER NOT NULL\n);\n\nINSERT INTO slots (slot_id, item_name, price_cents, stock) VALUES\n  ('A1', 'Sparkling Water', 175, 7),\n  ('A2', 'Salted Crisps',   150, 5);\n", "queries.sql": "-- queries.sql holds every question the server may ask the database.\n-- Each query starts with a comment of the form \"-- name: something\".\n-- A word with a colon in front, such as :slot, is a parameter.\n\n-- name: list_slots\nSELECT slot_id, item_name, price_cents, stock\nFROM slots\nORDER BY slot_id;\n", "routes.txt": "# routes.txt says which request runs which query.\n# Each line has four columns: the method, the path, the query name, and the shape of the answer.\n#   rows    the answer is a list of rows\n#   one     the answer is a single row, or 404 when nothing matches\n#   change  the answer says how many rows changed, or 409 when none did\n\nGET   /api/slots   list_slots   rows\n", "handlers.ts": "// handlers.ts holds your routes. A route says: when this request arrives, run this function.\n// Ready-made names: route, json, fail, db.all, db.get, db.run, db.transaction, queries.<name>.sql\n\nroute(\"GET\", \"/api/slots\", () => {\n  return json(db.all(queries.list_slots.sql));\n});\n", "handlers.py": "# handlers.py holds your routes. A route says: when this request arrives, run this function.\n# Ready-made names: route, ok, fail, db.all, db.get, db.run, db.transaction, queries[\"name\"][\"sql\"]\n\n\n@route(\"GET\", \"/api/slots\")\ndef list_slots(request):\n    return ok(db.all(queries[\"list_slots\"][\"sql\"]))\n", "style.css": "/* style.css controls how the pages look. Change a value and the preview updates at once. */\n\n:root {\n  --page: #f7f5ef;\n  --card: #ffffff;\n  --ink: #1f2933;\n  --quiet: #5b6673;\n  --line: #d9d4c7;\n  --accent: #0b6e6e;\n  --accent-text: #ffffff;\n  --bad: #a4262c;\n  --good: #25663a;\n}\n\n* { box-sizing: border-box; }\n\nbody {\n  margin: 0;\n  background: var(--page);\n  color: var(--ink);\n  font: 16px/1.5 system-ui, sans-serif;\n}\n\nheader {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: baseline;\n  justify-content: space-between;\n  gap: 8px 24px;\n  padding: 16px 24px;\n  background: var(--card);\n  border-bottom: 1px solid var(--line);\n}\n\nh1 { margin: 0; font-size: 1.4rem; }\n\nnav a { margin-right: 16px; color: var(--accent); }\n\nmain { max-width: 900px; margin: 0 auto; padding: 24px; }\n\n/* The machine is a grid of cards, one for each slot. */\n.machine {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(190px, 1fr));\n  gap: 16px;\n}\n\n.slot {\n  background: var(--card);\n  border: 1px solid var(--line);\n  border-radius: 10px;\n  padding: 16px;\n}\n\n.slot h2 { margin: 4px 0; font-size: 1.1rem; }\n.slot .price { margin: 0; font-weight: 700; }\n.slot .stock { margin: 0 0 12px; color: var(--quiet); }\n.slot-id { font-weight: 700; color: var(--accent); }\n\n/* The data-stock attribute is added by client.js, so CSS can react to the data. */\n.slot[data-stock=\"0\"] { opacity: 0.6; }\n.slot[data-stock=\"0\"] .stock { color: var(--bad); }\n\nbutton {\n  font: inherit;\n  font-weight: 700;\n  background: var(--accent);\n  color: var(--accent-text);\n  border: none;\n  border-radius: 6px;\n  padding: 8px 16px;\n  cursor: pointer;\n}\n\ninput {\n  font: inherit;\n  padding: 7px 10px;\n  border: 1px solid var(--line);\n  border-radius: 6px;\n}\n\n.message { min-height: 1.5em; font-weight: 700; }\n.message[data-kind=\"ok\"] { color: var(--good); }\n.message[data-kind=\"error\"] { color: var(--bad); }\n\ntable { width: 100%; border-collapse: collapse; background: var(--card); }\nth, td { text-align: left; padding: 8px 12px; border-bottom: 1px solid var(--line); }\n\n.detail { background: var(--card); border: 1px solid var(--line); border-radius: 10px; padding: 20px; }\n.detail h2 { margin-top: 0; }\n", "client.js": "// client.js is the only JavaScript in these pages. It reads data- attributes in the HTML,\n// asks the server for data, and fills the page in. You can build a whole page with\n// HTML and CSS alone, because this file does the JavaScript part for you.\n//\n//   data-get=\"/api/slots\"        Fetch this address when the page loads and show the answer inside this element.\n//   <template>                   Put the markup to repeat for every row inside the element. The markup needs one outer element.\n//   data-one                     The answer is a list, but show only its first row.\n//   data-field=\"item_name\"       Put the value of this column into the text of this element.\n//   data-format=\"euros\"          Show a number of cents as euros.\n//   data-href=\"item.html?slot={slot_id}\"   Build a link from the values of the row.\n//   data-post=\"/api/slots/{slot_id}/buy\"   Send a POST request when this button is clicked or this form is sent.\n//   data-success=\"Enjoy.\"        Set the message to show when the server answers OK.\n//   data-message                 Mark the element that shows messages.\n//\n// After a POST succeeds, the script fetches every data-get address on the page again, so the page shows the new data.\n// The script gives each row it builds the attribute data-generated, so that it can find and replace those rows later.\n//\n// In a text such as {slot_id}, the braces take a value from the row. In {query.slot} they\n// take a value from the address of the page, such as item.html?slot=A1.\n\n// The values after the question mark in the page's address, such as { slot: \"A1\" } for item.html?slot=A1.\n// The workbench supplies window.pageQuery because its pages do not have separate addresses.\n// On a real website you would read window.location.search instead.\nconst addressValues = Object.fromEntries(new URLSearchParams(window.pageQuery || window.location.search));\n\n// Replace every {name} or {query.name} in a text with a value, made safe for use in an address.\nfunction fillIn(text, row) {\n  return text.replace(/\\{(query\\.)?(\\w+)\\}/g, (_wholeMatch, queryPrefix, name) => {\n    const source = queryPrefix ? addressValues : row;\n    return encodeURIComponent(source[name] ?? \"\");\n  });\n}\n\n// Turn a number of cents into text such as \u20ac1.75.\nfunction formatValue(value, format) {\n  if (format === \"euros\") {\n    return \"\u20ac\" + (Number(value) / 100).toFixed(2);\n  }\n  return value;\n}\n\n// Show a message to the visitor, in the nearest element marked data-message.\nfunction showMessage(text, isError) {\n  const messageBox = document.querySelector(\"[data-message]\");\n  if (!messageBox) {\n    return;\n  }\n  messageBox.textContent = text;\n  messageBox.dataset.kind = isError ? \"error\" : \"ok\";\n}\n\n// Fetch the data for one section and rebuild its rows.\nasync function loadSection(section) {\n  // A section has no row yet, so its address can use {query.name} but not {column}.\n  const response = await fetch(fillIn(section.dataset.get, {}));\n  const answer = await response.json();\n  if (!response.ok) {\n    showMessage(answer.error, true);\n    return;\n  }\n\n  let rows = Array.isArray(answer) ? answer : [answer];\n  if (section.hasAttribute(\"data-one\")) {\n    rows = rows.slice(0, 1);\n  }\n\n  const template = section.querySelector(\"template\");\n  section.querySelectorAll(\"[data-generated]\").forEach((oldRow) => oldRow.remove());\n\n  for (const row of rows) {\n    const rowElement = template.content.firstElementChild.cloneNode(true);\n    rowElement.dataset.generated = \"\";\n\n    // Every column also becomes a data- attribute, so CSS can write rules such as [data-stock=\"0\"].\n    for (const [column, value] of Object.entries(row)) {\n      rowElement.dataset[column] = value;\n    }\n    rowElement.querySelectorAll(\"[data-field]\").forEach((element) => {\n      element.textContent = formatValue(row[element.dataset.field], element.dataset.format);\n    });\n    rowElement.querySelectorAll(\"[data-href]\").forEach((link) => {\n      link.setAttribute(\"href\", fillIn(link.dataset.href, row));\n    });\n    section.append(rowElement);\n  }\n}\n\n// Send a POST request for a button or a form, then refresh every section on the page.\nasync function sendPost(element, body) {\n  // A button inside a generated row can use that row's columns in its address, such as {slot_id}.\n  const row = element.closest(\"[data-generated]\")?.dataset ?? {};\n  const response = await fetch(fillIn(element.dataset.post, row), {\n    method: \"POST\",\n    headers: { \"Content-Type\": \"application/json\" },\n    body: JSON.stringify(body),\n  });\n  const answer = await response.json();\n  showMessage(response.ok ? element.dataset.success || \"Done.\" : answer.error, !response.ok);\n  if (response.ok) {\n    document.querySelectorAll(\"[data-get]\").forEach(loadSection);\n  }\n}\n\n// One listener on the whole document handles every button, including buttons added later.\ndocument.addEventListener(\"click\", (event) => {\n  const button = event.target.closest(\"button[data-post]\");\n  if (button) {\n    sendPost(button, {});\n  }\n});\n\n// A form sends its fields as JSON. Numbers in the fields are converted from text to numbers.\ndocument.addEventListener(\"submit\", (event) => {\n  const form = event.target.closest(\"form[data-post]\");\n  if (!form) {\n    return;\n  }\n  event.preventDefault();\n  const body = {};\n  for (const [name, value] of new FormData(form)) {\n    body[name] = value !== \"\" && !Number.isNaN(Number(value)) ? Number(value) : value;\n  }\n  sendPost(form, body);\n});\n\ndocument.querySelectorAll(\"[data-get]\").forEach(loadSection);\n"}, "advanced": {"index.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <title>My page</title>\n  <link rel=\"stylesheet\" href=\"style.css\">\n</head>\n<body>\n  <header>\n    <h1>My page</h1>\n  </header>\n\n  <main>\n    <p class=\"message\" data-message></p>\n\n    <!-- client.js fetches this address and repeats the template once for every row. -->\n    <section class=\"machine\" data-get=\"/api/slots\">\n      <template>\n        <article class=\"slot\">\n          <h2 data-field=\"item_name\"></h2>\n          <p class=\"price\" data-field=\"price_cents\" data-format=\"euros\"></p>\n          <p class=\"stock\"><span data-field=\"stock\"></span> left</p>\n        </article>\n      </template>\n    </section>\n  </main>\n\n  <script src=\"client.js\"></script>\n</body>\n</html>\n", "schema.sql": "-- schema.sql describes the tables and the rows they start with.\n-- Replace it with your own tables, then press \"Reset database\".\n\nDROP TABLE IF EXISTS slots;\n\nCREATE TABLE slots (\n  slot_id     TEXT PRIMARY KEY,\n  item_name   TEXT NOT NULL,\n  price_cents INTEGER NOT NULL,\n  stock       INTEGER NOT NULL\n);\n\nINSERT INTO slots (slot_id, item_name, price_cents, stock) VALUES\n  ('A1', 'Sparkling Water', 175, 7),\n  ('A2', 'Salted Crisps',   150, 5);\n", "queries.sql": "-- queries.sql holds every question the server may ask the database.\n-- Each query starts with a comment of the form \"-- name: something\".\n-- A word with a colon in front, such as :slot, is a parameter.\n\n-- name: list_slots\nSELECT slot_id, item_name, price_cents, stock\nFROM slots\nORDER BY slot_id;\n", "routes.txt": "# routes.txt says which request runs which query.\n# Each line has four columns: the method, the path, the query name, and the shape of the answer.\n#   rows    the answer is a list of rows\n#   one     the answer is a single row, or 404 when nothing matches\n#   change  the answer says how many rows changed, or 409 when none did\n\nGET   /api/slots   list_slots   rows\n", "handlers.ts": "// handlers.ts holds your routes. A route says: when this request arrives, run this function.\n// Ready-made names: route, json, fail, db.all, db.get, db.run, db.transaction, queries.<name>.sql\n\nroute(\"GET\", \"/api/slots\", () => {\n  return json(db.all(queries.list_slots.sql));\n});\n", "handlers.py": "# handlers.py holds your routes. A route says: when this request arrives, run this function.\n# Ready-made names: route, ok, fail, db.all, db.get, db.run, db.transaction, queries[\"name\"][\"sql\"]\n\n\n@route(\"GET\", \"/api/slots\")\ndef list_slots(request):\n    return ok(db.all(queries[\"list_slots\"][\"sql\"]))\n", "style.css": "/* style.css controls how the pages look. Change a value and the preview updates at once. */\n\n:root {\n  --page: #f7f5ef;\n  --card: #ffffff;\n  --ink: #1f2933;\n  --quiet: #5b6673;\n  --line: #d9d4c7;\n  --accent: #0b6e6e;\n  --accent-text: #ffffff;\n  --bad: #a4262c;\n  --good: #25663a;\n}\n\n* { box-sizing: border-box; }\n\nbody {\n  margin: 0;\n  background: var(--page);\n  color: var(--ink);\n  font: 16px/1.5 system-ui, sans-serif;\n}\n\nheader {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: baseline;\n  justify-content: space-between;\n  gap: 8px 24px;\n  padding: 16px 24px;\n  background: var(--card);\n  border-bottom: 1px solid var(--line);\n}\n\nh1 { margin: 0; font-size: 1.4rem; }\n\nnav a { margin-right: 16px; color: var(--accent); }\n\nmain { max-width: 900px; margin: 0 auto; padding: 24px; }\n\n/* The machine is a grid of cards, one for each slot. */\n.machine {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(190px, 1fr));\n  gap: 16px;\n}\n\n.slot {\n  background: var(--card);\n  border: 1px solid var(--line);\n  border-radius: 10px;\n  padding: 16px;\n}\n\n.slot h2 { margin: 4px 0; font-size: 1.1rem; }\n.slot .price { margin: 0; font-weight: 700; }\n.slot .stock { margin: 0 0 12px; color: var(--quiet); }\n.slot-id { font-weight: 700; color: var(--accent); }\n\n/* The data-stock attribute is added by client.js, so CSS can react to the data. */\n.slot[data-stock=\"0\"] { opacity: 0.6; }\n.slot[data-stock=\"0\"] .stock { color: var(--bad); }\n\nbutton {\n  font: inherit;\n  font-weight: 700;\n  background: var(--accent);\n  color: var(--accent-text);\n  border: none;\n  border-radius: 6px;\n  padding: 8px 16px;\n  cursor: pointer;\n}\n\ninput {\n  font: inherit;\n  padding: 7px 10px;\n  border: 1px solid var(--line);\n  border-radius: 6px;\n}\n\n.message { min-height: 1.5em; font-weight: 700; }\n.message[data-kind=\"ok\"] { color: var(--good); }\n.message[data-kind=\"error\"] { color: var(--bad); }\n\ntable { width: 100%; border-collapse: collapse; background: var(--card); }\nth, td { text-align: left; padding: 8px 12px; border-bottom: 1px solid var(--line); }\n\n.detail { background: var(--card); border: 1px solid var(--line); border-radius: 10px; padding: 20px; }\n.detail h2 { margin-top: 0; }\n", "client.js": "// client.js is the only JavaScript in these pages. It reads data- attributes in the HTML,\n// asks the server for data, and fills the page in. You can build a whole page with\n// HTML and CSS alone, because this file does the JavaScript part for you.\n//\n//   data-get=\"/api/slots\"        Fetch this address when the page loads and show the answer inside this element.\n//   <template>                   Put the markup to repeat for every row inside the element. The markup needs one outer element.\n//   data-one                     The answer is a list, but show only its first row.\n//   data-field=\"item_name\"       Put the value of this column into the text of this element.\n//   data-format=\"euros\"          Show a number of cents as euros.\n//   data-href=\"item.html?slot={slot_id}\"   Build a link from the values of the row.\n//   data-post=\"/api/slots/{slot_id}/buy\"   Send a POST request when this button is clicked or this form is sent.\n//   data-success=\"Enjoy.\"        Set the message to show when the server answers OK.\n//   data-message                 Mark the element that shows messages.\n//\n// After a POST succeeds, the script fetches every data-get address on the page again, so the page shows the new data.\n// The script gives each row it builds the attribute data-generated, so that it can find and replace those rows later.\n//\n// In a text such as {slot_id}, the braces take a value from the row. In {query.slot} they\n// take a value from the address of the page, such as item.html?slot=A1.\n\n// The values after the question mark in the page's address, such as { slot: \"A1\" } for item.html?slot=A1.\n// The workbench supplies window.pageQuery because its pages do not have separate addresses.\n// On a real website you would read window.location.search instead.\nconst addressValues = Object.fromEntries(new URLSearchParams(window.pageQuery || window.location.search));\n\n// Replace every {name} or {query.name} in a text with a value, made safe for use in an address.\nfunction fillIn(text, row) {\n  return text.replace(/\\{(query\\.)?(\\w+)\\}/g, (_wholeMatch, queryPrefix, name) => {\n    const source = queryPrefix ? addressValues : row;\n    return encodeURIComponent(source[name] ?? \"\");\n  });\n}\n\n// Turn a number of cents into text such as \u20ac1.75.\nfunction formatValue(value, format) {\n  if (format === \"euros\") {\n    return \"\u20ac\" + (Number(value) / 100).toFixed(2);\n  }\n  return value;\n}\n\n// Show a message to the visitor, in the nearest element marked data-message.\nfunction showMessage(text, isError) {\n  const messageBox = document.querySelector(\"[data-message]\");\n  if (!messageBox) {\n    return;\n  }\n  messageBox.textContent = text;\n  messageBox.dataset.kind = isError ? \"error\" : \"ok\";\n}\n\n// Fetch the data for one section and rebuild its rows.\nasync function loadSection(section) {\n  // A section has no row yet, so its address can use {query.name} but not {column}.\n  const response = await fetch(fillIn(section.dataset.get, {}));\n  const answer = await response.json();\n  if (!response.ok) {\n    showMessage(answer.error, true);\n    return;\n  }\n\n  let rows = Array.isArray(answer) ? answer : [answer];\n  if (section.hasAttribute(\"data-one\")) {\n    rows = rows.slice(0, 1);\n  }\n\n  const template = section.querySelector(\"template\");\n  section.querySelectorAll(\"[data-generated]\").forEach((oldRow) => oldRow.remove());\n\n  for (const row of rows) {\n    const rowElement = template.content.firstElementChild.cloneNode(true);\n    rowElement.dataset.generated = \"\";\n\n    // Every column also becomes a data- attribute, so CSS can write rules such as [data-stock=\"0\"].\n    for (const [column, value] of Object.entries(row)) {\n      rowElement.dataset[column] = value;\n    }\n    rowElement.querySelectorAll(\"[data-field]\").forEach((element) => {\n      element.textContent = formatValue(row[element.dataset.field], element.dataset.format);\n    });\n    rowElement.querySelectorAll(\"[data-href]\").forEach((link) => {\n      link.setAttribute(\"href\", fillIn(link.dataset.href, row));\n    });\n    section.append(rowElement);\n  }\n}\n\n// Send a POST request for a button or a form, then refresh every section on the page.\nasync function sendPost(element, body) {\n  // A button inside a generated row can use that row's columns in its address, such as {slot_id}.\n  const row = element.closest(\"[data-generated]\")?.dataset ?? {};\n  const response = await fetch(fillIn(element.dataset.post, row), {\n    method: \"POST\",\n    headers: { \"Content-Type\": \"application/json\" },\n    body: JSON.stringify(body),\n  });\n  const answer = await response.json();\n  showMessage(response.ok ? element.dataset.success || \"Done.\" : answer.error, !response.ok);\n  if (response.ok) {\n    document.querySelectorAll(\"[data-get]\").forEach(loadSection);\n  }\n}\n\n// One listener on the whole document handles every button, including buttons added later.\ndocument.addEventListener(\"click\", (event) => {\n  const button = event.target.closest(\"button[data-post]\");\n  if (button) {\n    sendPost(button, {});\n  }\n});\n\n// A form sends its fields as JSON. Numbers in the fields are converted from text to numbers.\ndocument.addEventListener(\"submit\", (event) => {\n  const form = event.target.closest(\"form[data-post]\");\n  if (!form) {\n    return;\n  }\n  event.preventDefault();\n  const body = {};\n  for (const [name, value] of new FormData(form)) {\n    body[name] = value !== \"\" && !Number.isNaN(Number(value)) ? Number(value) : value;\n  }\n  sendPost(form, body);\n});\n\ndocument.querySelectorAll(\"[data-get]\").forEach(loadSection);\n"}}}, "engines": {"ts": {"beginner": "// server.ts (Beginner level) is the middle layer between the browser and the database.\n// You do not need to change it. Read it to see how a request turns into a query.\n//\n// The rule is short. The address /api/list_slots runs the query named list_slots in queries.sql.\n// A query that starts with SELECT is a read, so it needs a GET request.\n// Every other query changes data, so it needs a POST request.\n// A query that changes no row at all is answered with 409, which means \"this could not be done\".\n//\n// The workbench gives this file three ready-made names: db, files and record.\n//   db.all(sql, params)    runs a query and returns every row\n//   db.run(sql, params)    runs a statement that changes data and returns { changes }\n//   db.transaction(work)   runs work as one unit that succeeds or fails as a whole\n//   files.read(name)       returns the text of a file in the project\n//   record(step)           tells the workbench what happened, so the timeline can draw it\n\n// Params holds the values that fill the :name parameters of a query.\ntype Params = Record<string, unknown>;\n// Incoming is the request as the workbench hands it to this file.\ntype Incoming = { method: string; path: string; query: Params; body: Params };\n\n// Read queries.sql and cut it into named queries. Each one starts with \"-- name: something\".\nfunction parseQueries(text: string) {\n  const queries: Record<string, { sql: string; line: number }> = {};\n  let currentName = \"\";\n  text.split(\"\\n\").forEach((lineText, index) => {\n    const header = lineText.match(/^--\\s*name:\\s*(\\w+)/);\n    if (header) {\n      currentName = header[1];\n      queries[currentName] = { sql: \"\", line: index + 1 };\n    } else if (currentName) {\n      queries[currentName].sql += lineText + \"\\n\";\n    }\n  });\n  return queries;\n}\n\n// Cut a query into its statements. This version splits on semicolons, so a semicolon inside a text value would confuse it.\nfunction splitStatements(sqlText: string): string[] {\n  const withoutComments = sqlText\n    .split(\"\\n\")\n    .filter((lineText) => !lineText.trim().startsWith(\"--\"))\n    .join(\"\\n\");\n  return withoutComments\n    .split(\";\")\n    .map((statement) => statement.trim())\n    .filter((statement) => statement.length > 0);\n}\n\n// A query is a read when it is one SELECT statement. Anything else may change data.\nfunction isReadQuery(statements: string[]) {\n  return statements.length === 1 && /^select/i.test(statements[0]);\n}\n\n// Run every statement of a query. A read returns rows. A write runs as one transaction and reports how many rows its last statement changed.\nfunction runQuery(sqlText: string, params: Params) {\n  const statements = splitStatements(sqlText);\n  if (isReadQuery(statements)) {\n    return { rows: db.all(statements[0], params), changes: 0, isRead: true };\n  }\n  let changes = 0;\n  db.transaction(() => {\n    for (const statement of statements) {\n      changes = db.run(statement, params).changes;\n    }\n  });\n  return { rows: [], changes, isRead: false };\n}\n\n// Answer one request. The argument says which method, path, address values and body arrived.\nfunction handleRequest(incoming: Incoming) {\n  if (!incoming.path.startsWith(\"/api/\")) {\n    return { status: 404, body: { error: `This server only answers addresses that start with /api/, not ${incoming.path}.` } };\n  }\n\n  const queries = parseQueries(files.read(\"queries.sql\"));\n  const queryName = incoming.path.slice(\"/api/\".length);\n  const query = queries[queryName];\n  if (!query) {\n    const known = Object.keys(queries).join(\", \");\n    return { status: 404, body: { error: `There is no query named ${queryName} in queries.sql. The names are: ${known}.` } };\n  }\n\n  // A read must use GET and a write must use POST.\n  const isRead = isReadQuery(splitStatements(query.sql));\n  const expectedMethod = isRead ? \"GET\" : \"POST\";\n  if (incoming.method !== expectedMethod) {\n    return { status: 405, body: { error: `The query ${queryName} needs ${expectedMethod}, but this request used ${incoming.method}.` } };\n  }\n\n  // The workbench listens to record() to draw the timeline. A real server has no such line.\n  record({\n    kind: \"route\",\n    text: `The path ${incoming.path} names the query ${queryName}.`,\n    file: \"queries.sql\",\n    line: query.line,\n    query: queryName,\n  });\n\n  // Values can arrive in the address (?slot=A1) or in the body. Both become parameters, and a value in the body wins when both have the same name.\n  const params = { ...incoming.query, ...incoming.body };\n  try {\n    const result = runQuery(query.sql, params);\n    if (result.isRead) {\n      return { status: 200, body: result.rows };\n    }\n    if (result.changes === 0) {\n      return { status: 409, body: { error: \"No row changed, so the request could not be carried out.\" } };\n    }\n    return { status: 200, body: { changes: result.changes } };\n  } catch (error) {\n    return { status: 400, body: { error: String((error as Error).message) } };\n  }\n}\n", "intermediate": "// server.ts (Intermediate level) is the middle layer between the browser and the database.\n// You do not need to change it. You decide what it does by editing routes.txt.\n//\n// For each request it finds the first line of routes.txt that matches the method and the path.\n// That line names a query in queries.sql, and says what shape the answer should have:\n//   rows    answers with a list of rows\n//   one     answers with the first row, or with 404 when there is none\n//   change  runs the query as a transaction and answers with the number of rows changed, or with 409 when none changed\n//\n// The workbench gives this file three ready-made names: db, files and record.\n//   db.all(sql, params)    runs a query and returns every row\n//   db.run(sql, params)    runs a statement that changes data and returns { changes }\n//   db.transaction(work)   runs work as one unit that succeeds or fails as a whole\n//   files.read(name)       returns the text of a file in the project\n//   record(step)           tells the workbench what happened, so the timeline can draw it\n\n// Params holds the values that fill the :name parameters of a query.\ntype Params = Record<string, unknown>;\n// Incoming is the request as the workbench hands it to this file.\ntype Incoming = { method: string; path: string; query: Params; body: Params };\n\n// Read queries.sql and cut it into named queries. Each one starts with \"-- name: something\".\nfunction parseQueries(text: string) {\n  const queries: Record<string, { sql: string; line: number }> = {};\n  let currentName = \"\";\n  text.split(\"\\n\").forEach((lineText, index) => {\n    const header = lineText.match(/^--\\s*name:\\s*(\\w+)/);\n    if (header) {\n      currentName = header[1];\n      queries[currentName] = { sql: \"\", line: index + 1 };\n    } else if (currentName) {\n      queries[currentName].sql += lineText + \"\\n\";\n    }\n  });\n  return queries;\n}\n\n// Read routes.txt. Every line that is not empty and does not start with # is one route.\nfunction parseRoutes(text: string) {\n  const routes: { method: string; path: string; regex: RegExp; names: string[]; queryName: string; shape: string; line: number }[] = [];\n  text.split(\"\\n\").forEach((lineText, index) => {\n    const trimmed = lineText.trim();\n    if (trimmed === \"\" || trimmed.startsWith(\"#\")) {\n      return;\n    }\n    const [method, path, queryName, shape] = trimmed.split(/\\s+/);\n\n    // A word such as :slot in the path becomes a pattern that captures that part of the address.\n    const names: string[] = [];\n    const pattern = path.replace(/:(\\w+)/g, (_wholeMatch, name) => {\n      names.push(name);\n      return \"([^/]+)\";\n    });\n    routes.push({ method, path, regex: new RegExp(\"^\" + pattern + \"$\"), names, queryName, shape, line: index + 1 });\n  });\n  return routes;\n}\n\n// Cut a query into its statements. This version splits on semicolons, so a semicolon inside a text value would confuse it.\nfunction splitStatements(sqlText: string): string[] {\n  const withoutComments = sqlText\n    .split(\"\\n\")\n    .filter((lineText) => !lineText.trim().startsWith(\"--\"))\n    .join(\"\\n\");\n  return withoutComments\n    .split(\";\")\n    .map((statement) => statement.trim())\n    .filter((statement) => statement.length > 0);\n}\n\n// Answer one request. The argument says which method, path, address values and body arrived.\nfunction handleRequest(incoming: Incoming) {\n  const routes = parseRoutes(files.read(\"routes.txt\"));\n  const queries = parseQueries(files.read(\"queries.sql\"));\n\n  // Find the first route whose path matches. Remember if any path matched, to tell 404 from 405.\n  let pathMatched = false;\n  for (const route of routes) {\n    const match = route.regex.exec(incoming.path);\n    if (!match) {\n      continue;\n    }\n    pathMatched = true;\n    if (route.method !== incoming.method) {\n      continue;\n    }\n\n    // The workbench listens to record() to draw the timeline. A real server has no such line.\n    record({\n      kind: \"route\",\n      text: `${incoming.method} ${incoming.path} matches the route ${route.method} ${route.path}, which runs the query ${route.queryName}.`,\n      file: \"routes.txt\",\n      line: route.line,\n      query: route.queryName,\n    });\n\n    const query = queries[route.queryName];\n    if (!query) {\n      return { status: 500, body: { error: `routes.txt line ${route.line} names the query ${route.queryName}, but queries.sql has no query with that name.` } };\n    }\n\n    // Values from the path win over values from the address, which win over values from the body.\n    const pathValues: Params = {};\n    route.names.forEach((name, index) => {\n      pathValues[name] = decodeURIComponent(match[index + 1]);\n    });\n    const params = { ...incoming.body, ...incoming.query, ...pathValues };\n\n    try {\n      const statements = splitStatements(query.sql);\n      if (route.shape === \"rows\" || route.shape === \"one\") {\n        const rows = db.all(statements[0], params);\n        if (route.shape === \"one\") {\n          return rows.length > 0\n            ? { status: 200, body: rows[0] }\n            : { status: 404, body: { error: \"Nothing matches that request.\" } };\n        }\n        return { status: 200, body: rows };\n      }\n\n      // The shape \"change\": run every statement as one transaction and count the rows changed by the last one.\n      let changes = 0;\n      db.transaction(() => {\n        for (const statement of statements) {\n          changes = db.run(statement, params).changes;\n        }\n      });\n      return changes > 0\n        ? { status: 200, body: { changes } }\n        : { status: 409, body: { error: \"No row changed, so the request could not be carried out.\" } };\n    } catch (error) {\n      return { status: 400, body: { error: String((error as Error).message) } };\n    }\n  }\n\n  if (pathMatched) {\n    return { status: 405, body: { error: `The path ${incoming.path} exists, but not for the method ${incoming.method}.` } };\n  }\n  return { status: 404, body: { error: `No route in routes.txt matches ${incoming.method} ${incoming.path}.` } };\n}\n", "advanced": "// server.ts (Advanced level) is a small framework. Your handlers.ts plugs into it.\n// It stores the routes you register, finds the one that matches each request,\n// and turns what your handler returns into an answer. Express and FastAPI do the same job on a larger scale.\n// You write the handlers. You can read this file, but the workbench keeps it fixed.\n//\n// The workbench gives this file three ready-made names: db, files and record.\n//   db.all(sql, params)    runs a query and returns every row\n//   db.get(sql, params)    runs a query and returns the first row, or undefined\n//   db.run(sql, params)    runs a statement that changes data and returns { changes }\n//   db.transaction(work)   runs work as one unit that succeeds or fails as a whole\n//   files.read(name)       returns the text of a file in the project\n//   record(step)           tells the workbench what happened, so the timeline can draw it\n//\n// This file also reads queries.sql once, and gives your handlers the result as queries.<name>.sql.\n\n// Params holds the values that fill the :name parameters of a query.\ntype Params = Record<string, unknown>;\n// Incoming is the request as the workbench hands it to this file.\ntype Incoming = { method: string; path: string; query: Params; body: Params };\n// What a handler receives: the incoming request, plus the words that were read from the path, such as { slot: \"A1\" }.\ntype HandlerRequest = Incoming & { params: Record<string, string> };\n// What a handler returns: a status code and a body.\ntype Answer = { status: number; body: unknown };\ntype Handler = (request: HandlerRequest) => Answer;\n\n// Every route that handlers.ts has registered, in the order it registered them.\nconst routes: { method: string; pattern: string; regex: RegExp; names: string[]; handler: Handler }[] = [];\n\n// Register a route. A word such as :slot in the pattern is captured from the address.\nfunction route(method: string, pattern: string, handler: Handler) {\n  const names: string[] = [];\n  const source = pattern.replace(/:(\\w+)/g, (_wholeMatch, name) => {\n    names.push(name);\n    return \"([^/]+)\";\n  });\n  routes.push({ method, pattern, regex: new RegExp(\"^\" + source + \"$\"), names, handler });\n}\n\n// These two small helpers build an answer.\nfunction json(body: unknown): Answer {\n  return { status: 200, body };\n}\nfunction fail(status: number, message: string): Answer {\n  return { status, body: { error: message } };\n}\n\n// Read queries.sql and cut it into named queries. Each one starts with \"-- name: something\".\nfunction parseQueries(text: string) {\n  const queries: Record<string, { sql: string; line: number }> = {};\n  let currentName = \"\";\n  text.split(\"\\n\").forEach((lineText, index) => {\n    const header = lineText.match(/^--\\s*name:\\s*(\\w+)/);\n    if (header) {\n      currentName = header[1];\n      queries[currentName] = { sql: \"\", line: index + 1 };\n    } else if (currentName) {\n      queries[currentName].sql += lineText + \"\\n\";\n    }\n  });\n  return queries;\n}\n// Your handlers use these as queries.list_slots.sql, queries.get_slot.sql and so on.\nconst queries = parseQueries(files.read(\"queries.sql\"));\n\n// Answer one request. The argument says which method, path, address values and body arrived.\nfunction handleRequest(incoming: Incoming): Answer {\n  let pathMatched = false;\n  for (const candidate of routes) {\n    const match = candidate.regex.exec(incoming.path);\n    if (!match) {\n      continue;\n    }\n    pathMatched = true;\n    if (candidate.method !== incoming.method) {\n      continue;\n    }\n\n    // The workbench listens to record() to draw the timeline. A real server has no such line.\n    record({\n      kind: \"route\",\n      text: `${incoming.method} ${incoming.path} matches the route ${candidate.method} ${candidate.pattern}.`,\n      file: \"handlers.ts\",\n      find: '\"' + candidate.pattern + '\"',\n    });\n\n    const params: Record<string, string> = {};\n    candidate.names.forEach((name, index) => {\n      params[name] = decodeURIComponent(match[index + 1]);\n    });\n\n    // A handler that throws an error must not crash the whole server, so the error becomes a 500 answer.\n    try {\n      return candidate.handler({ ...incoming, params });\n    } catch (error) {\n      return fail(500, \"The handler failed: \" + String((error as Error).message));\n    }\n  }\n\n  if (pathMatched) {\n    return fail(405, `The path ${incoming.path} exists, but not for the method ${incoming.method}.`);\n  }\n  return fail(404, `No route matches ${incoming.method} ${incoming.path}.`);\n}\n"}, "py": {"beginner": "\"\"\"server.py (Beginner level) is the middle layer between the browser and the database.\nYou do not need to change it. Read it to see how a request turns into a query.\n\nThe rule is short. The address /api/list_slots runs the query named list_slots in queries.sql.\nA query that starts with SELECT is a read, so it needs a GET request.\nEvery other query changes data, so it needs a POST request.\nA query that changes no row at all is answered with 409, which means \"this could not be done\".\n\nThe workbench gives this file these ready-made names:\n  db.all(sql, params)   runs a query and returns every row\n  db.run(sql, params)   runs a statement that changes data and returns a result with .changes\n  db.transaction()      is a \"with\" block whose statements succeed or fail as a whole\n  files.read(name)      returns the text of a file in the project\n  record(step)          tells the workbench what happened, so the timeline can draw it\n\"\"\"\n\nimport re\n\n\ndef parse_queries(text):\n    \"\"\"Read queries.sql and cut it into named queries. Each one starts with \"-- name: something\".\"\"\"\n    queries = {}\n    current_name = \"\"\n    for index, line_text in enumerate(text.split(\"\\n\")):\n        header = re.match(r\"^--\\s*name:\\s*(\\w+)\", line_text)\n        if header:\n            current_name = header.group(1)\n            queries[current_name] = {\"sql\": \"\", \"line\": index + 1}\n        elif current_name:\n            queries[current_name][\"sql\"] += line_text + \"\\n\"\n    return queries\n\n\ndef split_statements(sql_text):\n    \"\"\"Cut a query into its statements. This version splits on semicolons, so a semicolon inside a text value would confuse it.\"\"\"\n    lines = [line for line in sql_text.split(\"\\n\") if not line.strip().startswith(\"--\")]\n    parts = [part.strip() for part in \"\\n\".join(lines).split(\";\")]\n    return [part for part in parts if part]\n\n\ndef is_read_query(statements):\n    \"\"\"A query is a read when it is one SELECT statement. Anything else may change data.\"\"\"\n    return len(statements) == 1 and re.match(r\"select\", statements[0], re.IGNORECASE) is not None\n\n\ndef run_query(sql_text, params):\n    \"\"\"Run every statement of a query. A read returns rows. A write runs as one transaction and reports how many rows its last statement changed.\"\"\"\n    statements = split_statements(sql_text)\n    if is_read_query(statements):\n        return {\"rows\": db.all(statements[0], params), \"changes\": 0, \"is_read\": True}\n    changes = 0\n    with db.transaction():\n        for statement in statements:\n            changes = db.run(statement, params).changes\n    return {\"rows\": [], \"changes\": changes, \"is_read\": False}\n\n\ndef handle_request(incoming):\n    \"\"\"Answer one request. The argument is a dictionary with the keys method, path, query and body.\"\"\"\n    if not incoming[\"path\"].startswith(\"/api/\"):\n        return {\"status\": 404, \"body\": {\"error\": f\"This server only answers addresses that start with /api/, not {incoming['path']}.\"}}\n\n    queries = parse_queries(files.read(\"queries.sql\"))\n    query_name = incoming[\"path\"][len(\"/api/\"):]\n    query = queries.get(query_name)\n    if query is None:\n        known = \", \".join(queries.keys())\n        return {\"status\": 404, \"body\": {\"error\": f\"There is no query named {query_name} in queries.sql. The names are: {known}.\"}}\n\n    # A read must use GET and a write must use POST.\n    is_read = is_read_query(split_statements(query[\"sql\"]))\n    expected_method = \"GET\" if is_read else \"POST\"\n    if incoming[\"method\"] != expected_method:\n        return {\"status\": 405, \"body\": {\"error\": f\"The query {query_name} needs {expected_method}, but this request used {incoming['method']}.\"}}\n\n    # The workbench listens to record() to draw the timeline. A real server has no such line.\n    record({\n        \"kind\": \"route\",\n        \"text\": f\"The path {incoming['path']} names the query {query_name}.\",\n        \"file\": \"queries.sql\",\n        \"line\": query[\"line\"],\n        \"query\": query_name,\n    })\n\n    # Values can arrive in the address (?slot=A1) or in the body. Both become parameters, and a value in the body wins when both have the same name.\n    params = {**incoming[\"query\"], **incoming[\"body\"]}\n    try:\n        result = run_query(query[\"sql\"], params)\n    except Exception as error:\n        return {\"status\": 400, \"body\": {\"error\": str(error)}}\n\n    if result[\"is_read\"]:\n        return {\"status\": 200, \"body\": result[\"rows\"]}\n    if result[\"changes\"] == 0:\n        return {\"status\": 409, \"body\": {\"error\": \"No row changed, so the request could not be carried out.\"}}\n    return {\"status\": 200, \"body\": {\"changes\": result[\"changes\"]}}\n", "intermediate": "\"\"\"server.py (Intermediate level) is the middle layer between the browser and the database.\nYou do not need to change it. You decide what it does by editing routes.txt.\n\nFor each request it finds the first line of routes.txt that matches the method and the path.\nThat line names a query in queries.sql, and says what shape the answer should have:\n  rows    answers with a list of rows\n  one     answers with the first row, or with 404 when there is none\n  change  runs the query as a transaction and answers with the number of rows changed, or with 409 when none changed\n\nThe workbench gives this file these ready-made names:\n  db.all(sql, params)   runs a query and returns every row\n  db.run(sql, params)   runs a statement that changes data and returns a result with .changes\n  db.transaction()      is a \"with\" block whose statements succeed or fail as a whole\n  files.read(name)      returns the text of a file in the project\n  record(step)          tells the workbench what happened, so the timeline can draw it\n\"\"\"\n\nimport re\nfrom urllib.parse import unquote\n\n\ndef parse_queries(text):\n    \"\"\"Read queries.sql and cut it into named queries. Each one starts with \"-- name: something\".\"\"\"\n    queries = {}\n    current_name = \"\"\n    for index, line_text in enumerate(text.split(\"\\n\")):\n        header = re.match(r\"^--\\s*name:\\s*(\\w+)\", line_text)\n        if header:\n            current_name = header.group(1)\n            queries[current_name] = {\"sql\": \"\", \"line\": index + 1}\n        elif current_name:\n            queries[current_name][\"sql\"] += line_text + \"\\n\"\n    return queries\n\n\ndef parse_routes(text):\n    \"\"\"Read routes.txt. Every line that is not empty and does not start with # is one route.\"\"\"\n    routes = []\n    for index, line_text in enumerate(text.split(\"\\n\")):\n        trimmed = line_text.strip()\n        if trimmed == \"\" or trimmed.startswith(\"#\"):\n            continue\n        columns = trimmed.split()\n        method, path, query_name, shape = (columns + [\"\", \"\", \"\", \"\"])[:4]\n\n        # A word such as :slot in the path becomes a pattern that captures that part of the address.\n        names = re.findall(r\":(\\w+)\", path)\n        regex = re.compile(\"^\" + re.sub(r\":\\w+\", \"([^/]+)\", path) + \"$\")\n        routes.append({\"method\": method, \"path\": path, \"regex\": regex, \"names\": names,\n                       \"query_name\": query_name, \"shape\": shape, \"line\": index + 1})\n    return routes\n\n\ndef split_statements(sql_text):\n    \"\"\"Cut a query into its statements. This version splits on semicolons, so a semicolon inside a text value would confuse it.\"\"\"\n    lines = [line for line in sql_text.split(\"\\n\") if not line.strip().startswith(\"--\")]\n    parts = [part.strip() for part in \"\\n\".join(lines).split(\";\")]\n    return [part for part in parts if part]\n\n\ndef handle_request(incoming):\n    \"\"\"Answer one request. The argument is a dictionary with the keys method, path, query and body.\"\"\"\n    routes = parse_routes(files.read(\"routes.txt\"))\n    queries = parse_queries(files.read(\"queries.sql\"))\n\n    # Find the first route whose path matches. Remember if any path matched, to tell 404 from 405.\n    path_matched = False\n    for route in routes:\n        match = route[\"regex\"].match(incoming[\"path\"])\n        if not match:\n            continue\n        path_matched = True\n        if route[\"method\"] != incoming[\"method\"]:\n            continue\n\n        # The workbench listens to record() to draw the timeline. A real server has no such line.\n        record({\n            \"kind\": \"route\",\n            \"text\": f\"{incoming['method']} {incoming['path']} matches the route {route['method']} {route['path']}, which runs the query {route['query_name']}.\",\n            \"file\": \"routes.txt\",\n            \"line\": route[\"line\"],\n            \"query\": route[\"query_name\"],\n        })\n\n        query = queries.get(route[\"query_name\"])\n        if query is None:\n            return {\"status\": 500, \"body\": {\"error\": f\"routes.txt line {route['line']} names the query {route['query_name']}, but queries.sql has no query with that name.\"}}\n\n        # Values from the path win over values from the address, which win over values from the body.\n        path_values = {name: unquote(value) for name, value in zip(route[\"names\"], match.groups())}\n        params = {**incoming[\"body\"], **incoming[\"query\"], **path_values}\n\n        try:\n            statements = split_statements(query[\"sql\"])\n            if route[\"shape\"] in (\"rows\", \"one\"):\n                rows = db.all(statements[0], params)\n                if route[\"shape\"] == \"one\":\n                    if rows:\n                        return {\"status\": 200, \"body\": rows[0]}\n                    return {\"status\": 404, \"body\": {\"error\": \"Nothing matches that request.\"}}\n                return {\"status\": 200, \"body\": rows}\n\n            # The shape \"change\": run every statement as one transaction and count the rows changed by the last one.\n            changes = 0\n            with db.transaction():\n                for statement in statements:\n                    changes = db.run(statement, params).changes\n            if changes > 0:\n                return {\"status\": 200, \"body\": {\"changes\": changes}}\n            return {\"status\": 409, \"body\": {\"error\": \"No row changed, so the request could not be carried out.\"}}\n        except Exception as error:\n            return {\"status\": 400, \"body\": {\"error\": str(error)}}\n\n    if path_matched:\n        return {\"status\": 405, \"body\": {\"error\": f\"The path {incoming['path']} exists, but not for the method {incoming['method']}.\"}}\n    return {\"status\": 404, \"body\": {\"error\": f\"No route in routes.txt matches {incoming['method']} {incoming['path']}.\"}}\n", "advanced": "\"\"\"server.py (Advanced level) is a small framework. Your handlers.py plugs into it.\nIt stores the routes you register, finds the one that matches each request,\nand turns what your handler returns into an answer. Flask and FastAPI do the same job on a larger scale.\nYou write the handlers. You can read this file, but the workbench keeps it fixed.\n\nThe workbench gives this file these ready-made names:\n  db.all(sql, params)   runs a query and returns every row\n  db.get(sql, params)   runs a query and returns the first row, or None\n  db.run(sql, params)   runs a statement that changes data and returns a result with .changes\n  db.transaction()      is a \"with\" block whose statements succeed or fail as a whole\n  files.read(name)      returns the text of a file in the project\n  record(step)          tells the workbench what happened, so the timeline can draw it\n\nThis file also reads queries.sql once, and gives your handlers the result as queries[\"name\"][\"sql\"].\n\"\"\"\n\nimport re\nfrom urllib.parse import unquote\n\n# Every route that handlers.py has registered, in the order it registered them.\nroutes = []\n\n\nclass Request:\n    \"\"\"What a handler receives. The path words, the address values and the body are dictionaries.\"\"\"\n\n    def __init__(self, method, path, params, query, body):\n        self.method = method\n        self.path = path\n        self.params = params\n        self.query = query\n        self.body = body\n\n\ndef route(method, pattern):\n    \"\"\"A decorator. Put @route(\"GET\", \"/api/slots\") above a function to register it as a route.\n    A word such as :slot in the pattern is captured from the address.\"\"\"\n\n    def register(handler):\n        names = re.findall(r\":(\\w+)\", pattern)\n        regex = re.compile(\"^\" + re.sub(r\":\\w+\", \"([^/]+)\", pattern) + \"$\")\n        routes.append({\"method\": method, \"pattern\": pattern, \"regex\": regex, \"names\": names, \"handler\": handler})\n        return handler\n\n    return register\n\n\ndef ok(body):\n    \"\"\"Build an answer with status 200.\"\"\"\n    return {\"status\": 200, \"body\": body}\n\n\ndef fail(status, message):\n    \"\"\"Build an answer with an error status and a message.\"\"\"\n    return {\"status\": status, \"body\": {\"error\": message}}\n\n\ndef parse_queries(text):\n    \"\"\"Read queries.sql and cut it into named queries. Each one starts with \"-- name: something\".\"\"\"\n    queries = {}\n    current_name = \"\"\n    for index, line_text in enumerate(text.split(\"\\n\")):\n        header = re.match(r\"^--\\s*name:\\s*(\\w+)\", line_text)\n        if header:\n            current_name = header.group(1)\n            queries[current_name] = {\"sql\": \"\", \"line\": index + 1}\n        elif current_name:\n            queries[current_name][\"sql\"] += line_text + \"\\n\"\n    return queries\n\n\n# Your handlers use these as queries[\"list_slots\"][\"sql\"] and so on.\nqueries = parse_queries(files.read(\"queries.sql\"))\n\n\ndef handle_request(incoming):\n    \"\"\"Answer one request. The argument is a dictionary with the keys method, path, query and body.\"\"\"\n    path_matched = False\n    for candidate in routes:\n        match = candidate[\"regex\"].match(incoming[\"path\"])\n        if not match:\n            continue\n        path_matched = True\n        if candidate[\"method\"] != incoming[\"method\"]:\n            continue\n\n        # The workbench listens to record() to draw the timeline. A real server has no such line.\n        record({\n            \"kind\": \"route\",\n            \"text\": f\"{incoming['method']} {incoming['path']} matches the route {candidate['method']} {candidate['pattern']}.\",\n            \"file\": \"handlers.py\",\n            \"find\": '\"' + candidate[\"pattern\"] + '\"',\n        })\n\n        params = {name: unquote(value) for name, value in zip(candidate[\"names\"], match.groups())}\n        request = Request(incoming[\"method\"], incoming[\"path\"], params, incoming[\"query\"], incoming[\"body\"])\n\n        # A handler that raises an error must not crash the whole server, so the error becomes a 500 answer.\n        try:\n            return candidate[\"handler\"](request)\n        except Exception as error:\n            return fail(500, f\"The handler failed: {error}\")\n\n    if path_matched:\n        return fail(405, f\"The path {incoming['path']} exists, but not for the method {incoming['method']}.\")\n    return fail(404, f\"No route matches {incoming['method']} {incoming['path']}.\")\n"}}, "bridge": "// Injected into the preview frame before the student's own scripts run.\n// It replaces fetch so that requests go to the workbench instead of the network,\n// and it reports clicks, link navigation, changes to the page and errors.\n//\n// The workbench replaces the two @@ markers below with this page's address values and its document number\n// before it puts the script into the frame.\n(function () {\n  var ADDRESS_QUERY = \"@@QUERY@@\";\n  var DOCUMENT_NUMBER = @@DOC@@;\n  window.pageQuery = ADDRESS_QUERY;\n\n  // Every message carries the document number, so the workbench can ignore messages from a page it has already replaced.\n  var send = function (message) { message.__wb = true; message.doc = DOCUMENT_NUMBER; parent.postMessage(message, \"*\"); };\n\n  // A request waits here until the workbench sends the server's answer back.\n  var pendingReplies = {};\n  var lastRequestId = 0;\n\n  window.fetch = function (url, options) {\n    options = options || {};\n    return new Promise(function (resolve, reject) {\n      lastRequestId += 1;\n      pendingReplies[lastRequestId] = { resolve: resolve, reject: reject };\n      send({\n        type: \"fetch\",\n        id: lastRequestId,\n        method: String(options.method || \"GET\").toUpperCase(),\n        url: String(url),\n        body: typeof options.body === \"string\" ? options.body : null,\n      });\n    });\n  };\n\n  window.addEventListener(\"message\", function (event) {\n    var data = event.data;\n    if (!data || !data.__wb) { return; }\n    if (data.type === \"reply\" && pendingReplies[data.id]) {\n      var waiting = pendingReplies[data.id];\n      delete pendingReplies[data.id];\n      waiting.resolve(new Response(data.bodyText, { status: data.status, headers: { \"Content-Type\": \"application/json\" } }));\n    }\n    // A changed stylesheet replaces the text of its <style> element, so the page restyles without reloading.\n    if (data.type === \"css\") {\n      var style = document.querySelector('style[data-file=\"' + data.name + '\"]');\n      if (style) { style.textContent = data.text; }\n    }\n  });\n\n  // A short description of an element for the timeline, such as <button> \u201cBuy\u201d.\n  function labelFor(element) {\n    var text = (element.textContent || element.value || \"\").trim().replace(/\\s+/g, \" \").slice(0, 30);\n    var tag = element.tagName.toLowerCase();\n    return text ? \"<\" + tag + \"> \u201c\" + text + \"\u201d\" : \"<\" + tag + \">\";\n  }\n\n  // Link clicks to pages in the project become navigation inside the workbench. Button clicks are reported as clicks.\n  document.addEventListener(\"click\", function (event) {\n    var link = event.target.closest && event.target.closest(\"a\");\n    if (link && link.getAttribute(\"href\") && !/^(https?:|mailto:|#)/.test(link.getAttribute(\"href\"))) {\n      event.preventDefault();\n      send({ type: \"navigate\", href: link.getAttribute(\"href\"), label: labelFor(link) });\n      return;\n    }\n    var target = event.target.closest && event.target.closest(\"button, a, input[type=submit]\");\n    if (target) { send({ type: \"click\", label: labelFor(target) }); }\n  }, true);\n\n  document.addEventListener(\"submit\", function () {\n    send({ type: \"click\", label: \"a form being sent\", viaSubmit: true });\n  }, true);\n\n  // A form that nothing handled would reload the page. Say so, and stop it.\n  window.addEventListener(\"submit\", function (event) {\n    if (!event.defaultPrevented) {\n      event.preventDefault();\n      send({ type: \"error\", message: \"A form was sent, but no script handled it. Add data-post to the form, or write a script that handles the submit event.\" });\n    }\n  });\n\n  // Report what changed on the page, once the changes have stopped for a moment.\n  var changedElements = [];\n  var settleTimer = null;\n  // A short name for an element, such as section#list or article.slot, to say where a change happened.\n  function shortName(element) {\n    var name = element.tagName.toLowerCase();\n    if (element.id) { name += \"#\" + element.id; }\n    else if (element.classList && element.classList.length) { name += \".\" + element.classList[0]; }\n    return name;\n  }\n  var observer = new MutationObserver(function (records) {\n    // Each record describes one change. We keep the changed element and the parent that contains it.\n    records.forEach(function (record) {\n      record.addedNodes.forEach(function (node) {\n        if (node.nodeType === 1 && node.tagName !== \"SCRIPT\" && node.tagName !== \"STYLE\") { changedElements.push({ node: node, parent: record.target }); }\n        if (node.nodeType === 3 && record.target.nodeType === 1) { changedElements.push({ node: record.target, parent: record.target, changed: true }); }\n      });\n      if (record.type === \"characterData\" || record.type === \"attributes\") {\n        if (record.target.nodeType === 1 && record.attributeName !== \"data-wb-flash\") { changedElements.push({ node: record.target, parent: record.target, changed: true }); }\n      }\n    });\n    clearTimeout(settleTimer);\n    settleTimer = setTimeout(function () {\n      if (!changedElements.length) { return; }\n      // Count the changes by parent and flash each parent briefly, so the student can see where the page changed.\n      var parents = {};\n      changedElements.forEach(function (entry) {\n        var target = entry.parent.nodeType === 1 ? entry.parent : document.body;\n        var key = shortName(target);\n        parents[key] = (parents[key] || 0) + 1;\n        if (target.setAttribute) { target.setAttribute(\"data-wb-flash\", \"\"); setTimeout(function () { target.removeAttribute(\"data-wb-flash\"); }, 900); }\n      });\n      var summary = Object.keys(parents).slice(0, 3).map(function (key) { return parents[key] + (parents[key] === 1 ? \" element\" : \" elements\") + \" in <\" + key + \">\"; }).join(\", \");\n      send({ type: \"dom\", count: changedElements.length, summary: summary });\n      changedElements = [];\n    }, 120);\n  });\n  // Start watching once the page has been built, so the first drawing of the page is not reported as a change.\n  function startWatching() {\n    observer.observe(document.documentElement, { childList: true, subtree: true, characterData: true, attributes: true });\n  }\n  if (document.readyState === \"loading\") { document.addEventListener(\"DOMContentLoaded\", startWatching); } else { startWatching(); }\n\n  window.addEventListener(\"error\", function (event) { send({ type: \"error\", message: event.message }); });\n  window.addEventListener(\"unhandledrejection\", function (event) { send({ type: \"error\", message: String(event.reason) }); });\n})();\n"};
